-- ١) القصّةُ الأولى: آدمُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-adam',
  'القصّةُ الأولى: آدمُ عليه السلام',
  'فأخبر تعالى أنه خاطب الملائكة قائلا لهم: {إني جاعل في الأرض خليفة} أعلم بما يريد أن يخلق من آدم وذريته الذين يخلف بعضهم بعضا كما قال: {وهو الذي جعلكم…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَإِذْ قَالَ رَبُّكَ لِلْمَلَٰٓئِكَةِ إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ} <strong>(سورة البقرة ٢، الآية ٣٠)</strong></p>
<p>{وَعَلَّمَ ءَادَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمْ صَٰدِقِينَ} <strong>(سورة البقرة ٢، الآية ٣١)</strong></p>
<p>{وَإِذْ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِءَادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ أَبَىٰ وَٱسْتَكْبَرَ وَكَانَ مِنَ ٱلْكَٰفِرِينَ} <strong>(سورة البقرة ٢، الآية ٣٤)</strong></p>
<p>{قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ} <strong>(سورة الأعراف ٧، الآية ٢٣)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>فأخبر تعالى أنه خاطب الملائكة قائلا لهم: {إني جاعل في الأرض خليفة} أعلم بما يريد أن يخلق من آدم وذريته الذين يخلف بعضهم بعضا كما قال: {وهو الذي جعلكم خلائف الأرض} وقال: {ويجعلكم خلفاء الأرض} فأخبرهم بذلك على سبيل التنويه بخلق آدم وذريته، كما يخبر بالأمر العظيم قبل كونه، فقالت الملائكة سائلين على وجه الاستكشاف والاستعلام عن وجه الحكمة، لا على وجه الاعتراض والتنقص لبني آدم والحسد لهم، كما قد يتوهمه بعض جهلة المفسرين، قالوا: {أتجعل فيها من يفسد فيها ويسفك الدماء}.</p>
<p>قيل علموا أن ذلك كائن بما رأوا ممن كان قبل آدم من الجن والبن. قاله قتادة.</p>
<p>وقال عبد الله بن عمر: كانت الجن قبل آدم بألفي عام فسفكوا الدماء، فبعث الله إليهم جندا من الملائكة فطردوهم إلى جزائر البحور. وعن ابن عباس نحوه. وعن الحسن: ألهموا ذلك. وقيل: لما اطلعوا عليه من اللوح المحفوظ، فقيل أطلعهم عليه هاروت وماروت عن ملك فوقهما يقال له السجل. رواه ابن أبي حاتم عن أبي جعفر الباقر. وقيل: لأنهم علموا أن الأرض لا يخلق منها إلا من يكون بهذه المثابة غالبا.</p>
<p>{ونحن نسبح بحمدك ونقدس لك} أي نعبدك دائما لا يعصيك منا أحد، فإن كان المراد بخلق هؤلاء أن يعبدوك فها نحن لا نفتر ليلا ولا نهارا.</p>
<p>{قال إني أعلم ما لا تعلمون} أي أعلم من المصلحة الراجحة في خلق هؤلاء ما لا تعلمون، أي سيوجد منهم الأنبياء والمرسلون والصديقون والشهداء.</p>
<p>ثم بين لهم شرف آدم عليهم في العلم فقال: {وعلم آدم الأسماء كلها}. قال ابن عباس: هي هذه الأسماء التي يتعارف بها الناس: إنسان، ودابة، وأرض وسهل، وبحر، وجبل، وجمل، وحمار، وأشباه ذلك من الأمم وغيرها. وفي رواية: علمه اسم الصحفة، والقدر، حتى الفسوة والفسية. وقال مجاهد: علمه اسم كل دابة، وكل طير وكل شيء. وكذا قال سعيد بن جبير وقتادة وغير واحد.</p>
<p>وقال الربيع: علمه أسماء الملائكة. وقال عبد الرحمن بن زيد: علمه أسماء ذريته. والصحيح: أنه علمه أسماء الذوات وأفعالها مكبرها ومصغرها، كما أشار إليه ابن عباس رضي الله عنهما.</p>
<p>وذكر البخاري هنا ما رواه هو ومسلم من طريق سعيد وهشام عن قتادة، عن أنس بن مالك، عن رسول الله صلى الله عليه وسلم قال: "يجتمع المؤمنون يوم القيامة فيقولون لو استشفعنا إلى ربنا، فيأتون آدم فيقولون أنت أبو البشر، خلقك الله بيده، وأسجد لك ملائكته، وعلمك أسماء كل شيء" وذكر تمام الحديث.</p>
<p>{ثم عرضهم على الملائكة فقال أنبئوني بأسماء هؤلاء إن كنتم صادقين}. قال الحسن البصري: لما أراد الله خلق آدم، قالت الملائكة: لا يخلق ربنا خلقا إلا كنا أعلم منه. فابتلوا بهذا. وذلك قوله {إن كنتم صادقين}. وقيل غير ذلك كما بسطناه في التفسير.</p>
<p>{قالوا سبحانك لا علم لنا إلا ما علمتنا إنك أنت العليم الحكيم} أي سبحانك أن يحيط أحد بشيء من علمك من غير تعليمك، كما قال: {ولا يحيطون بشيء من علمه إلا بما شاء}.</p>
<blockquote>البابُ في الكتاب: باب: ما ورد في خلق آدم عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%A8%D8%A7%D8%A8%3A_%D9%85%D8%A7_%D9%88%D8%B1%D8%AF_%D9%81%D9%8A_%D8%AE%D9%84%D9%82_%D8%A2%D8%AF%D9%85_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — باب: ما ورد في خلق آدم عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: إدريسُ عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%A8%D8%A7%D8%A8%3A_%D9%85%D8%A7_%D9%88%D8%B1%D8%AF_%D9%81%D9%8A_%D8%AE%D9%84%D9%82_%D8%A2%D8%AF%D9%85_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84',
  '["آدم عليه السلام","قصص الأنبياء","ابن كثير"]'::jsonb,
  '{"القصّة":"١ من ٢٥","الكتاب":"قصص الأنبياء — ابن كثير (جزؤه الأول)","الباب":"باب: ما ورد في خلق آدم عليه السلام","الرخصة":"ويكي مصدر — رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)"}'::jsonb,
  'published', 250,
  '2026-10-22T00:00:00.000Z'::timestamptz
where not exists (select 1 from public.items where section_id = 'prophets_stories' and slug = 'prophet-adam');

-- ٢) القصّةُ الثانية: إدريسُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-idris',
  'القصّةُ الثانية: إدريسُ عليه السلام',
  'قال الله تعالى: {واذكر في الكتاب إدريس إنه كان صديقا نبيا. ورفعناه مكانا عليا} فإدريس عليه السلام قد أثنى الله عليه ووصفه بالنبوة والصديقية، وهو خنوخ…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِدْرِيسَ ۚ إِنَّهُۥ كَانَ صِدِّيقًۭا نَّبِيًّۭا} <strong>(سورة مريم ١٩، الآية ٥٦)</strong></p>
<p>{وَرَفَعْنَٰهُ مَكَانًا عَلِيًّا} <strong>(سورة مريم ١٩، الآية ٥٧)</strong></p>
<p>{وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ ۖ كُلٌّۭ مِّنَ ٱلصَّٰبِرِينَ} <strong>(سورة الأنبياء ٢١، الآية ٨٥)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قال الله تعالى: {واذكر في الكتاب إدريس إنه كان صديقا نبيا. ورفعناه مكانا عليا} فإدريس عليه السلام قد أثنى الله عليه ووصفه بالنبوة والصديقية، وهو خنوخ هذا. وهو في عمود نسب رسول الله صلى الله عليه وسلم على ما ذكره غير واحد من علماء النسب.</p>
<p>وذكر ابن اسحاق أنه أول من خط بالقلم، وقد أدرك من حياة آدم ثلاثمائة سنة وثماني سنين. وقد قال طائفة من الناس أنه المشار إليه في حديث معاوية بن الحكم السلمي لما سأل رسول الله صلى الله عليه وسلم عن الخط بالرمل فقال: " إنه كان نبي يخط به فمن وافق خطه فذاك".</p>
<p>ويزعم كثير من علماء التفسير والأحكام أنه أول من تكلم في ذلك، ويسمونه هرمس الهرامسة، ويكذبون عليه أشياء كثيرة كما كذبوا على غيره من الأنبياء والعلماء والحكماء والأولياء.</p>
<p>وقوله تعالى: {ورفعناه مكانا عليا} هو كما ثبت في "الصحيحين" في حديث الإسراء: أن رسول الله صلى الله عليه وسلم مر به وهو في السماء الرابعة. وقد روى ابن جرير عن يونس عن عبد الأعلى، عن ابن وهب، عن جرير بن حازم، عن الأعمش، عن شمر بن عطية، عن هلال بن يساف قال: سأل ابن عباس كعبا وأنا حاضر فقال له: ما قول الله تعالى لإدريس {ورفعناه مكانا عليا}؟ فقال كعب: أما إدريس فإن الله أوحى إليه: أني أرفع لك كل يوم مثل جميع عمل بني آدم - لعله من أهل زمانه - فأحب أن يزداد عملا، فأتاه خليل له من الملائكة، فقال "له": إن الله أوحى إلي كذا وكذا فكلم ملك الموت حتى ازداد عملا، فحمله بين جناحيه ثم صعد به إلى السماء، فلما كان في السماء الرابعة تلقاه ملك الموت منحدرا، فكلم ملك الموت في الذي كلمه فيه إدريس، فقال: وأين إدريس؟ قال هو ذا على ظهري، فقال ملك الموت: يا للعجب! بعثت وقيل لي اقبض روح إدريس في السماء الرابعة، فجعلت أقول: كيف أقبض روحه في السماء الرابعة وهو في الأرض؟! فقبض روحه هناك. فذلك قول الله عز وجل {ورفعناه مكانا عليا}.</p>
<p>ورواه ابن أبي حاتم عند تفسيرها. وعنده فقال لذلك الملك سل لي ملك الموت كم بقي من عمري؟ فسأله وهو معه: كم بقي من عمره؟ فقال: لا أدري حتى أنظر، فنظر فقال إنك لتسألني عن رجل ما بقي من عمره إلا طرفة عين، فنظر الملك إلى تحت جناحه إلى إدريس فإذا هو قد قبض وهو لا يشعر. وهذا من الإسرائيليات، وفي بعضه نكارة.</p>
<p>وقول ابن أبي نجيح عن مجاهد في قوله: {ورفعناه مكانا عليا} قال: إدريس رفع ولم يمت كما رفع عيسى. إن أراد أنه لم يمت إلى الآن ففي هذا نظر، وإن أراد أنه رفع حيا إلى السماء ثم قبض هناك. فلا ينافي ما تقدم عن كعب الأحبار. والله أعلم.</p>
<p>وقال العوفي عن ابن عباس في قوله: {ورفعناه مكانا عليا} : رفع إلى السماء السادسة فمات بها، وهكذا قال الضحاك. والحديث المتفق عليه من أنه في السماء الرابعة أصح، وهو قول مجاهد وغير واحد. وقال الحسن البصري: {ورفعناه مكانا عليا} قال: إلى الجنة، وقال قائلون رفع في حياة أبيه يرد بن مهلاييل والله أعلم. وقد زعم بعضهم أن إدريس لم يكن قبل نوح بل في زمان بني إسرائيل.</p>
<blockquote>البابُ في الكتاب: ذكر إدريس عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%B0%D9%83%D8%B1_%D8%A5%D8%AF%D8%B1%D9%8A%D8%B3_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — ذكر إدريس عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: نوحٌ عليه السلام.</p>',
