-- ٣) القصّةُ الثالثة: نوحٌ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-nuh',
  'القصّةُ الثالثة: نوحٌ عليه السلام',
  'ويزعم أهل الكتاب أن نوحا عليه السلام لما ركب في السفينة كان عمره ستمائة سنة. وقدمنا عن ابن عباس مثله، وزاد: وعاش بعد ذلك ثلاثمائة وخمسين سنة، وفي هذا…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَلَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَلَبِثَ فِيهِمْ أَلْفَ سَنَةٍ إِلَّا خَمْسِينَ عَامًۭا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمْ ظَٰلِمُونَ} <strong>(سورة العنكبوت ٢٩، الآية ١٤)</strong></p>
<p>{تَجْرِى بِأَعْيُنِنَا جَزَآءًۭ لِّمَن كَانَ كُفِرَ} <strong>(سورة القمر ٥٤، الآية ١٤)</strong></p>
<p>{وَقَالَ نُوحٌۭ رَّبِّ لَا تَذَرْ عَلَى ٱلْأَرْضِ مِنَ ٱلْكَٰفِرِينَ دَيَّارًا} <strong>(سورة نوح ٧١، الآية ٢٦)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>ويزعم أهل الكتاب أن نوحا عليه السلام لما ركب في السفينة كان عمره ستمائة سنة. وقدمنا عن ابن عباس مثله، وزاد: وعاش بعد ذلك ثلاثمائة وخمسين سنة، وفي هذا القول نظر. ثم إن لم يكن الجمع بينه وبين دلالة القرآن فهو خطأ محض. فإن القرآن يقتضي أن نوحا مكث في قومه بعد البعثة وقبل الطوفان ألف سنة إلا خمسين عاما فأخذهم الطوفان وهم ظالمون. ثم الله أعلم كم عاش بعد ذلك؟</p>
<p>فإن كان ما ذكر محفوظا عن ابن عباس - من أنه بعث وله أربعمائة وثمانون سنة، وأنه عاش بعد الطوفان ثلاثمائة وخمسين سنة - فيكون قد عاش على هذا ألف سنة وسبعمائة وثمانين سنة.</p>
<p>وأما قبره عليه السلام: فروى ابن جرير والأزرقي عن عبد الرحمن بن سابط أو غيره من التابعين مرسلا، أن قبر نوح عليه السلام بالمسجد الحرام.</p>
<p>وهذا أقوى وأثبت من الذي يذكره كثير من المتأخرين، من أنه ببلدة بالبقاع تعرف اليوم بكرك نوح، وهناك جامع قد بني بسبب ذلك فيما ذكر. والله أعلم.</p>
<blockquote>البابُ في الكتاب: ذكر شيء من أخبار نوح نفسه عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%B0%D9%83%D8%B1_%D8%B4%D9%8A%D8%A1_%D9%85%D9%86_%D8%A3%D8%AE%D8%A8%D8%A7%D8%B1_%D9%86%D9%88%D8%AD_%D9%86%D9%81%D8%B3%D9%87_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — ذكر شيء من أخبار نوح نفسه عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: هودٌ عليه السلام.</p>',
