-- ٤) القصّةُ الرابعة: هودٌ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-hud',
  'القصّةُ الرابعة: هودٌ عليه السلام',
  'والمقصود أن عادا - وهم عاد الأولى - كانوا أول من عبد الأصنام بعد الطوفان. وكانت أصنامهم ثلاثة: صدا، وصمودا،…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{۞ وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۚ أَفَلَا تَتَّقُونَ} <strong>(سورة الأعراف ٧، الآية ٦٥)</strong></p>
<p>{وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًۭا ۚ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ ۖ إِنْ أَنتُمْ إِلَّا مُفْتَرُونَ} <strong>(سورة هود ١١، الآية ٥٠)</strong></p>
<p>{قَالَ إِنَّمَا ٱلْعِلْمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرْسِلْتُ بِهِۦ وَلَٰكِنِّىٓ أَرَىٰكُمْ قَوْمًۭا تَجْهَلُونَ} <strong>(سورة الأحقاف ٤٦، الآية ٢٣)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>والمقصود أن عادا - وهم عاد الأولى - كانوا أول من عبد الأصنام بعد الطوفان. وكانت أصنامهم ثلاثة: صدا، وصمودا، وهرا.</p>
<p>فبعث الله فيهم أخاهم هودا عليه السلام فدعاهم إلى الله، كما قال تعالى بعد ذكر قوم نوح، وما كان من أمرهم في سورة الأعراف: {وإلى عاد أخاهم هودا قال يا قوم اعبدوا الله ما لكم من إله غيره أفلا تتقون، قال الملأ الذين كفروا من قومه إنا لنراك في سفاهة وإنا لنظنك من الكاذبين قال يا قوم ليس بي سفاهة ولكني رسول من رب العالمين، أبلغكم رسالات ربي وأنا لكم ناصح أمين، أوعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم واذكروا إذ جعلكم خلفاء من بعد قوم نوح وزادكم في الخلق بسطة فاذكروا آلاء الله لعلكم تفلحون، قالوا أجئتنا لنعبد الله وحده ونذر ما كان يعبد آباؤنا فأتنا بما تعدنا إن كنت من الصادقين قال قد وقع عليكم من ربكم رجس وغضب أتجادلونني في أسماء سميتموها أنتم وآباؤكم ما نزل الله بها من سلطان فانتظروا إني معكم من المنتظرين، فأنجيناه والذين معه برحمة منا وقطعنا دابر الذين كذبوا بآياتنا وما كانوا مؤمنين}.</p>
<p>وقال تعالى بعد ذكر قصة نوح في سورة هود: {وإلى عاد أخاهم هودا قال يا قوم اعبدوا الله ما لكم من إله غيره إن أنتم إلا مفترون، يا قوم لا أسألكم عليه أجرا إن أجري إلا على الذي فطرني أفلا تعقلون، ويا قوم استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدرارا ويزدكم قوة إلى قوتكم ولا تتولوا مجرمين، قالوا يا هود ما جئتنا ببينة وما نحن بتاركي آلهتنا عن قولك وما نحن لك بمؤمنين إن نقول إلا اعتراك بعض آلهتنا بسوء قال إني أشهد الله واشهدوا أني بريء مما تشركون، من دونه فكيدوني جميعا ثم لا تنظرون، إني توكلت على الله ربي وربكم ما من دابة إلا هو آخذ بناصيتها إن ربي على صراط مستقيم، فإن تولوا فقد أبلغتكم ما أرسلت به إليكم ويستخلف ربي قوما غيركم ولا تضرونه شيئا إن ربي على كل شيء حفيظ ولما جاء أمرنا نجينا هودا والذين آمنوا معه برحمة منا ونجيناهم من عذاب غليظ، وتلك عاد جحدوا بآيات ربهم وعصوا رسله واتبعوا أمر كل جبار عنيد، وأتبعوا في هذه الدنيا لعنة ويوم القيامة ألا إن عادا كفروا ربهم ألا بعدا لعاد قوم هود}.</p>
<p>وقال تعالى في سورة {قد أفلح المؤمنون} بعد قصة قوم نوح: {ثم أنشأنا من بعدهم قرنا آخرين، فأرسلنا فيهم رسولا منهم أن اعبدوا الله ما لكم من إله غيره أفلا تتقون، وقال الملأ من قومه الذين كفروا وكذبوا بلقاء الآخرة وأترفناهم في الحياة الدنيا ما هذا إلا بشر مثلكم يأكل مما تأكلون منه ويشرب مما تشربون، ولئن أطعتم بشرا مثلكم إنكم إذا لخاسرون، أيعدكم أنكم إذا متم وكنتم ترابا وعظاما أنكم مخرجون هيهات هيهات لما توعدون، إن هي إلا حياتنا الدنيا نموت ونحيا وما نحن بمبعوثين، إن هو إلا رجل افترى على الله كذبا وما نحن له بمؤمنين، قال رب انصرني بما كذبوني، قال عما قليل ليصبحن نادمين، فأخذتهم الصيحة بالحق فجعلناهم غثاء فبعدا للقوم الظالمين}.</p>
<blockquote>البابُ في الكتاب: قصة هود عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D9%87%D9%88%D8%AF_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة هود عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: صالحٌ عليه السلام.</p>',
