-- ٥) القصّةُ الخامسة: صالحٌ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-salih',
  'القصّةُ الخامسة: صالحٌ عليه السلام',
  'فبعث الله فيهم رجلا منهم وهو عبد الله ورسوله: صالح بن عبيد بن ماسح بن عبيد بن حادر بن ثمود بن عاثر بن ارم بن نوح فدعاهم إلى عبادة الله وحده لا شريك…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌۭ مِّن رَّبِّكُمْ ۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةًۭ ۖ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ ۖ وَلَا تَمَسُّوهَا بِسُوٓءٍۢ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌۭ} <strong>(سورة الأعراف ٧، الآية ٧٣)</strong></p>
<p>{وَيَٰقَوْمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةًۭ فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍۢ فَيَأْخُذَكُمْ عَذَابٌۭ قَرِيبٌۭ} <strong>(سورة هود ١١، الآية ٦٤)</strong></p>
<p>{إِنَّا مُرْسِلُوا۟ ٱلنَّاقَةِ فِتْنَةًۭ لَّهُمْ فَٱرْتَقِبْهُمْ وَٱصْطَبِرْ} <strong>(سورة القمر ٥٤، الآية ٢٧)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>فبعث الله فيهم رجلا منهم وهو عبد الله ورسوله: صالح بن عبيد بن ماسح بن عبيد بن حادر بن ثمود بن عاثر بن ارم بن نوح فدعاهم إلى عبادة الله وحده لا شريك له، وأن يخلعوا الأصنام والأنداد ولا يشركوا به شيئا. فآمنت به طائفة منهم، وكفر جمهورهم، ونالوا منه بالمقال والفعال، وهموا بقتله، وقتلوا الناقة التي جعلها الله حجة عليهم، فأخذهم الله أخذ عزيز مقتدر.</p>
<p>كما قال تعالى في سورة الأعراف: {وإلى ثمود أخاهم صالحا قال يا قوم اعبدوا الله ما لكم من إله غيره قد جاءتكم بينة من ربكم هذه ناقة الله لكم آية فذروها تأكل في أرض الله ولا تمسوها بسوء فيأخذكم عذاب أليم، واذكروا إذ جعلكم خلفاء من بعد عاد وبوأكم في الأرض تتخذون من سهولها قصورا وتنحتون الجبال بيوتا فاذكروا آلاء الله ولا تعثوا في الأرض مفسدين، قال الملأ الذين استكبروا من قومه للذين استضعفوا لمن آمن منهم أتعلمون أن صالحا مرسل من ربه قالوا إنا بما أرسل به مؤمنون، قال الذين استكبروا إنا بالذي آمنتم به كافرون، فعقروا الناقة وعتوا عن أمر ربهم وقالوا يا صالح ائتنا بما تعدنا إن كنت من المرسلين، فأخذتهم الرجفة فأصبحوا في دارهم جاثمين، فتولى عنهم وقال يا قوم لقد أبلغتكم رسالة ربي ونصحت لكم ولكن لا تحبون الناصحين}.</p>
<p>وقال تعالى في سورة هود: {وإلى ثمود أخاهم صالحا قال يا قوم اعبدوا الله ما لكم من إله غيره هو أنشأكم من الأرض واستعمركم فيها فاستغفروه ثم توبوا إليه إن ربي قريب مجيب، قالوا يا صالح قد كنت فينا مرجوا قبل هذا أتنهانا أن نعبد ما يعبد آباؤنا وإننا لفي شك مما تدعونا إليه مريب، قال يا قوم أرأيتم إن كنت على بينة من ربي وآتاني منه رحمة فمن ينصرني من الله إن عصيته، فما تزيدونني غير تخسير، ويا قوم هذه ناقة الله لكم آية فذروها تأكل في أرض الله ولا تمسوها بسوء فيأخذكم عذاب قريب، فعقروها فقال تمتعوا في داركم ثلاثة أيام ذلك وعد غير مكذوب، فلما جاء أمرنا نجينا صالحا والذين آمنوا معه برحمة منا ومن خزي يومئذ إن ربك هو القوي العزيز، وأخذ الذين ظلموا الصيحة فأصبحوا في ديارهم جاثمين، كأن لم يغنوا فيها ألا إن ثمود كفروا ربهم ألا بعدا لثمود}.</p>
<p>وقال تعالى في سورة الحجر:{ولقد كذب أصحاب الحجر المرسلين، وآتيناهم آياتنا فكانوا عنها معرضين، وكانوا ينحتون من الجبال بيوتا آمنين، فأخذتهم الصيحة مصبحين، فما أغنى عنهم ما كانوا يكسبون}.</p>
<p>وقال سبحانه وتعالى في سورة سبحان: {وما منعنا أن نرسل بالآيات إلا أن كذب بها الأولون وآتينا ثمود الناقة مبصرة فظلموا بها وما نرسل بالآيات إلا تخويفا}.</p>
<blockquote>البابُ في الكتاب: قصة صالح عليه السلام نبي ثمود — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D8%B5%D8%A7%D9%84%D8%AD_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85_%D9%86%D8%A8%D9%8A_%D8%AB%D9%85%D9%88%D8%AF">قصصُ الأنبياء لابن كثير — قصة صالح عليه السلام نبي ثمود</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: إبراهيمُ الخليل عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D8%B5%D8%A7%D9%84%D8%AD_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85_%D9%86%D8%A8%D9%8A_%D8%AB%D9%85%D9%88%D8%AF',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84',
  '["صالح عليه السلام","قصص الأنبياء","ابن كثير"]'::jsonb,
  '{"القصّة":"٥ من ٢٥","الكتاب":"قصص الأنبياء — ابن كثير (جزؤه الأول)","الباب":"قصة صالح عليه السلام نبي ثمود","الرخصة":"ويكي مصدر — رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)"}'::jsonb,
  'published', 210,
