-- ٦) القصّةُ السادسة: إبراهيمُ الخليل عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-ibrahim',
  'القصّةُ السادسة: إبراهيمُ الخليل عليه السلام',
  'قالوا: وانطلق تارخ بابنه إبراهيم وامرأته سارة وابن أخيه لوط بن هاران، فخرج بهم من أرض الكلدانيين إلى أرض الكنعانيين، فنزلوا حران، فمات فيها تارخ وله…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{۞ وَإِذْ قَالَ إِبْرَٰهِيمُ لِأَبِيهِ ءَازَرَ أَتَتَّخِذُ أَصْنَامًا ءَالِهَةً ۖ إِنِّىٓ أَرَىٰكَ وَقَوْمَكَ فِى ضَلَٰلٍۢ مُّبِينٍۢ} <strong>(سورة الأنعام ٦، الآية ٧٤)</strong></p>
<p>{قُلْنَا يَٰنَارُ كُونِى بَرْدًۭا وَسَلَٰمًا عَلَىٰٓ إِبْرَٰهِيمَ} <strong>(سورة الأنبياء ٢١، الآية ٦٩)</strong></p>
<p>{فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ ۚ قَالَ يَٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ ۖ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ} <strong>(سورة الصافات ٣٧، الآية ١٠٢)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قالوا: وانطلق تارخ بابنه إبراهيم وامرأته سارة وابن أخيه لوط بن هاران، فخرج بهم من أرض الكلدانيين إلى أرض الكنعانيين، فنزلوا حران، فمات فيها تارخ وله مائتان وخمسون سنة. وهذا يدل على أنه لم يولد بحران، وإنما مولده بأرض الكلدانيين وهي أرض بابل وما والاها.</p>
<p>ثم ارتحلوا قاصدين أرض الكنعانيين، وهي بلاد بيت المقدس، فأقاموا بحران وهي أرض الكلدانيين في ذلك الزمان، وكذلك أرض الجزيرة والشام أيضا. وكانوا يعبدون الكواكب السبعة. والذين عمروا مدينة دمشق كانوا على هذا الدين، يستقبلون القطب الشمالي ويعبدون الكواكب السبعة بأنواع من الفعال والمقال. ولهذا كان على كل باب من أبواب دمشق السبعة القديمة هيكل لكوكب منها، ويعملون لها أعياد وقرابين.</p>
<p>وهكذا كان أهل حران يعبدون الكواكب والأصنام وكل من كان على وجه الأرض كانوا كفارا، سوى إبراهيم الخليل وامرأته وابن أخيه لوط عليهم السلام.</p>
<p>وكان الخليل عليه السلام هو الذي أزال الله به تلك الشرور وأبطل به ذاك الضلال، فإن الله سبحانه وتعالى آتاه رشده في صغره، وابتعثه رسولا، واتخذه خليلا في كبره، قال الله تعالى: ولقد آتينا إبراهيم رشده من قبل وكنا به عالمين}. أي كان أهلا لذلك.</p>
<p>وقال تعالى: {وإبراهيم إذ قال لقومه اعبدوا الله واتقوه ذلكم خير لكم إن كنتم تعلمون، إنما تعبدون من دون الله أوثانا وتخلقون إفكا إن الذين تعبدون من دون الله لا يملكون لكم رزقا فابتغوا عند الله الرزق واعبدوه واشكروا له إليه ترجعون، وإن تكذبوا فقد كذب أمم من قبلكم وما على الرسول إلا البلاغ المبين، أولم يروا كيف يبدئ الله الخلق ثم يعيده إن ذلك على الله يسير قل سيروا في الأرض فانظروا كيف بدأ الخلق ثم الله ينشئ النشأة الآخرة إن الله على كل شيء قدير، يعذب من يشاء ويرحم من يشاء وإليه تقلبون، وما أنتم بمعجزين في الأرض ولا في السماء وما لكم من دون الله من ولي ولا نصير، والذين كفروا بآيات الله ولقائه أولئك يئسوا من رحمتي وأولئك لهم عذاب أليم، فما كان جواب قومه إلا أن قالوا اقتلوه أو حرقوه فأنجاه الله من النار إن في ذلك لآيات لقوم يؤمنون، وقال إنما اتخذتم من دون الله أوثانا مودة بينكم في الحياة الدنيا ثم يوم القيامة يكفر بعضكم ببعض ويلعن بعضكم بعضا ومأواكم النار وما لكم من ناصرين، فآمن له لوط وقال إني مهاجر إلى ربي إنه هو العزيز الحكيم، ووهبنا له إسحاق ويعقوب وجعلنا في ذريته النبوة والكتاب وآتيناه أجره في الدنيا وآتيناه أجره في الدنيا وإنه في الآخرة لمن الصالحين}.</p>
<p>ثم ذكر تعالى مناظرته لأبيه وقومه كما سنذكره إن شاء الله تعالى.</p>
<blockquote>البابُ في الكتاب: قصة إبراهيم الخليل عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D8%A5%D8%A8%D8%B1%D8%A7%D9%87%D9%8A%D9%85_%D8%A7%D9%84%D8%AE%D9%84%D9%8A%D9%84_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة إبراهيم الخليل عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: لوطٌ عليه السلام.</p>',
