-- ٧) القصّةُ السابعة: لوطٌ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-lut',
  'القصّةُ السابعة: لوطٌ عليه السلام',
  'وكان لوط قد نزح عن محلة عمه الخليل عليهما السلام بأمره له وأذنه، فنزل بمدينة سدوم من أرض غور، زغر، وكان أم تلك المحله، ولها أرض ومعتملات وقرى، مضافة…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍۢ مِّنَ ٱلْعَٰلَمِينَ} <strong>(سورة الأعراف ٧، الآية ٨٠)</strong></p>
<p>{أَتَأْتُونَ ٱلذُّكْرَانَ مِنَ ٱلْعَٰلَمِينَ} <strong>(سورة الشعراء ٢٦، الآية ١٦٥)</strong></p>
<p>{وَلَمَّا جَآءَتْ رُسُلُنَا لُوطًۭا سِىٓءَ بِهِمْ وَضَاقَ بِهِمْ ذَرْعًۭا وَقَالَ هَٰذَا يَوْمٌ عَصِيبٌۭ} <strong>(سورة هود ١١، الآية ٧٧)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>وكان لوط قد نزح عن محلة عمه الخليل عليهما السلام بأمره له وأذنه، فنزل بمدينة سدوم من أرض غور، زغر، وكان أم تلك المحله، ولها أرض ومعتملات وقرى، مضافة إليها ولها أهل من أفجر الناس وأكفرهم وأسوأهم طوية، وأرداهم سريرة وسيرة، يقطعون السبيل ويأتون في ناديهم المنكر، ولا يتناهون عن منكر فعلوه لبئس ما كانوا يفعلون.</p>
<p>ابتدعوا فاحشة لم يسبقهم إليها أحد من بني آدم، وهي إتيان الذكران من العالمين، وترك ما خلق الله من النسوان لعباده الصالحين.</p>
<p>فدعاهم لوط إلى عبادة الله تعالى وحده لا شريك له، ونهاهم عن تعاطي هذه المحرمات، والفواحش المنكرات، والأفاعيل المستقبحات، فتمادوا على ضلالهم وطغيانهم، واستمروا على فجورهم وكفرانهم، فأحل الله بهم من البأس الذي لا يرد ما لم يكن في خلدهم وحسبانهم، وجعلهم مثله في العالمين، وعبرة يتعظ بها الألباء من العالمين.</p>
<p>ولهذا ذكر الله تعالى قصتهم في غير ما موضع في كتابه المبين، فقال تعالى في سورة الأعراف: {ولوطا إذ قال لقومه أتأتون الفاحشة ما سبقكم بها من أحد من العالمين، إنكم لتأتون الرجال شهوة من دون النساء بل أنتم قوم مسرفون، وما كان جواب قومه إلا أن قالوا أخرجوهم من قريتكم إنهم أناس يتطهرون، فأنجيناه وأهله إلا امرأته كانت من الغابرين، وأمطرنا عليهم مطرا فانظر كيف كان عاقبة المجرمين}.</p>
<p>وقال تعالى في سورة هود: {ولقد جاءت رسلنا إبراهيم بالبشرى قالوا سلاما قال سلام فما لبث أن جاء بعجل حنيذ، فلما رأى أيديهم لا تصل إليه نكرهم وأوجس منهم خيفة قالوا لا تخف إنا أرسلنا إلى قوم لوط، وامرأته قائمة فضحكت فبشرناها بإسحاق ومن وراء إسحاق يعقوب، قالت يا ويلتا أألد وأنا عجوز وهذا بعلي شيخا إن هذا لشيء عجيب، قالوا أتعجبين من أمر الله رحمة الله وبركاته عليكم أهل البيت إنه حميد مجيد، فلما ذهب عن إبراهيم الروع وجاءته البشرى يجادلنا في قوم لوط، إن إبراهيم لحليم أواه منيب، يا إبراهيم أعرض عن هذا إنه قد جاء أمر ربك وإنهم آتيهم عذاب غير مردود، ولما جاءت رسلنا لوطا سيء بهم وضاق بهم ذرعا وقال هذا يوم عصيب، وجاءه قومه يهرعون إليه ومن قبل كانوا يعملون السيئات قال يا قوم هؤلاء بناتي هن أطهر لكم فاتقوا الله ولا تخزوني في ضيفي أليس منكم رجل رشيد، قالوا لقد علمت ما لنا في بناتك من حق وإنك لتعلم ما نريد، قال لو أن لي بكم قوة أو آوي إلى ركن شديد، قالوا يا لوط إنا رسل ربك لن يصلوا إليك فأسر بأهلك بقطع من الليل فأسر بأهلك بقطع من الليل ولا يلتفت منكم أحد إلا امرأتك إنه مصيبها ما أصابهم إن موعدهم الصبح أليس الصبح بقريب، فلما جاء أمرنا جعلنا عاليها سافلها وأمطرنا عليها حجارة من سجيل منضود، مسومة عند ربك وما هي من الظالمين ببعيد}.</p>
<blockquote>البابُ في الكتاب: قصة لوط عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D9%84%D9%88%D8%B7_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة لوط عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: شعيبٌ عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D9%84%D9%88%D8%B7_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84',
  '["لوط عليه السلام","قصص الأنبياء","ابن كثير"]'::jsonb,
  '{"القصّة":"٧ من ٢٥","الكتاب":"قصص الأنبياء — ابن كثير (جزؤه الأول)","الباب":"قصة لوط عليه السلام","الرخصة":"ويكي مصدر — رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)"}'::jsonb,
