-- ٨) القصّةُ الثامنة: شعيبٌ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-shuaib',
  'القصّةُ الثامنة: شعيبٌ عليه السلام',
  'كان أهل مدين قوما عربا يسكنون مدينتهم مدين، التي هي قريبة من أرض معان من أطراف الشام، مما يلي ناحية الحجار قريبا من بحيرة قوم لوط. وكانوا بعدهم بمدة…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًۭا ۗ قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ ۖ قَدْ جَآءَتْكُم بَيِّنَةٌۭ مِّن رَّبِّكُمْ ۖ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا ۚ ذَٰلِكُمْ خَيْرٌۭ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ} <strong>(سورة الأعراف ٧، الآية ٨٥)</strong></p>
<p>{قَالُوا۟ يَٰشُعَيْبُ أَصَلَوٰتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءَابَآؤُنَآ أَوْ أَن نَّفْعَلَ فِىٓ أَمْوَٰلِنَا مَا نَشَٰٓؤُا۟ ۖ إِنَّكَ لَأَنتَ ٱلْحَلِيمُ ٱلرَّشِيدُ} <strong>(سورة هود ١١، الآية ٨٧)</strong></p>
<p>{إِنِّى لَكُمْ رَسُولٌ أَمِينٌۭ} <strong>(سورة الشعراء ٢٦، الآية ١٧٨)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>كان أهل مدين قوما عربا يسكنون مدينتهم مدين، التي هي قريبة من أرض معان من أطراف الشام، مما يلي ناحية الحجار قريبا من بحيرة قوم لوط. وكانوا بعدهم بمدة قريبة. ومدين مدينة عرفت بالقبيلة وهم من بني مدين بن مديان بن إبراهيم الخليل.</p>
<p>قال: ويقال له بالسريانية يترون وفي هذا نظر ويقال: شعيب بن يشخر بن لاوي بن يعقوب. ويقال: شعيب بن نويب بن عيفا بن مدين بن إبراهيم. ويقال شعيب بن صيفور بن عيفا بن ثابت بن مدين بن إبراهيم. وقيل غير ذلك في نسبه.</p>
<p>وعن وهب بن منبه انه قال: شعيب وملغم ممن آمن بإبراهيم يوم أحرق بالنار، وهاجرا معه إلى الشام، فزوجهما بنتي لوط عليه السلام. ذكره ابن قتيبة. وفي هذا كله نظر أيضا والله تعالى أعلم.</p>
<p>وذكر أبو عمرو بن عبد البر في الاستيعاب، في ترجمة سلمة بن سعد العنزي: أنه قدم على رسول الله صلى الله عليه وسلم فأسلم وانتسب إلى عنزة، فقال: "نعم الحي عنزة، مبغي عليهم منصورين، قوم شعيب وأختان موسى".</p>
<p>فلو صح هذا لدل على أن شعيبا صهر موسى وأنه من قبيلة من العرب العاربة، يقال لهم عنزة، لا أنهم من عنزة بن أسد بن ربيعة بن نزار بن معد بن عدنان فإن هؤلاء بعده بدهر طويل. والله أعلم.</p>
<p>وفي حديث أبي ذر الذي في صحيح ابن حبان في ذكر الأنبياء والرسل قال : "أربعة من العرب هود وصالح وشعيب ونبيك يا أبا ذر" وكان بعض السلف يسمي شعيبا خطيب الأنبياء يعني لفصاحته وعلو عبارته وبلاغته في دعاية قومه إلى الإيمان برسالته.</p>
<p>وقد روى ابن إسحاق بن بشر عن جويبر ومقاتل، عن الضحاك، عن ابن عباس قال: كان رسول الله صلى الله عليه وسلم إذا ذكر شعيبا قال: (ذاك خطيب الأنبياء).</p>
<p>وكان أهل مدين كفارا، يقطعون السبيل ويخيفون المارة، ويعبدون الأيكة وهي شجرة من الأيك حولها غيضة ملتفة بها.</p>
<p>وكانوا من أسوأ الناس معاملة، يبخسون المكيال والميزان، ويطففون فيهما، يأخذون بالزائد ويدفعون بالناقص.</p>
<p>فبعث الله فيهم رجلا منهم وهو رسول الله شعيب عليه السلام، فدعاهم إلى عبادة الله وحده لا شريك له، ونهاهم عن تعاطي هذه الأفاعيل القبيحة، من بخس الناس أشيائهم واخافتهم لهم في سبلهم وطرقاتهم فآمن به بعضهم وكفر أكثرهم، حتى أحل الله بهم البأس الشديد. وهو الولي الحميد.</p>
<p>كما قال تعالى: {وإلى مدين أخاهم شعيبا قال يا قوم اعبدوا الله ما لكم من إله غيره قد جاءتكم بينة من ربكم} أي دلالة وحجة واضحة وبرهان قاطع على صدق ما جئتكم به وأنه أرسلني، وهو ما أجرى الله على يديه من المعجزات التي لم تنقل إلينا تفصيلا وإن كان هذا اللفظ قد دل عليها إجمالا.</p>
<p>{فأوفوا الكيل والميزان ولا تبخسوا الناس أشياءهم ولا تفسدوا في الأرض بعد إصلاحها}. أمرهم بالعدل ونهاهم عن الظلم وتوعدهم على خلاف ذلك فقال: {ذلكم خير لكم إن كنتم مؤمنين، ولا تقعدوا بكل صراط} أي طريق {توعدون} أي تتوعدون الناس بأخذ أموالهم من مكوس وغير ذلك، وتخيفون السبل.</p>
<p>قال السدي في "تفسيره" عن الصحابة "ولا تقعدوا بكل صراط توعدون" أنهم كانوا يأخذون العشور من أموال المارة.</p>
<p>وقال إسحاق بن بشر عن جويبر عن الضحاك، عن ابن عباس قال: كانوا قوما طغاة بغاة يجلسون على الطريق يبخسون الناس يعني يعشرونهم. وكانوا أول من سن ذلك.</p>
<blockquote>البابُ في الكتاب: قصة مدين قوم شعيب عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D9%85%D8%AF%D9%8A%D9%86_%D9%82%D9%88%D9%85_%D8%B4%D8%B9%D9%8A%D8%A8_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة مدين قوم شعيب عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: إسماعيلُ عليه السلام.</p>',
