-- ٩) القصّةُ التاسعة: إسماعيلُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-ismail',
  'القصّةُ التاسعة: إسماعيلُ عليه السلام',
  'أما في الصورة فلأنه كان ولده أزيد من ثلاثة عشر سنة، وأم أنه وحيد في المعنى فإنه هو الذي هاجر به أبوه ومعه أمه هاجر، وكان صغيرا رضيعا فيما قيل،…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَٱذْكُرْ فِى ٱلْكِتَٰبِ إِسْمَٰعِيلَ ۚ إِنَّهُۥ كَانَ صَادِقَ ٱلْوَعْدِ وَكَانَ رَسُولًۭا نَّبِيًّۭا} <strong>(سورة مريم ١٩، الآية ٥٤)</strong></p>
<p>{وَكَانَ يَأْمُرُ أَهْلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرْضِيًّۭا} <strong>(سورة مريم ١٩، الآية ٥٥)</strong></p>
<p>{فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعْىَ قَالَ يَٰبُنَىَّ إِنِّىٓ أَرَىٰ فِى ٱلْمَنَامِ أَنِّىٓ أَذْبَحُكَ فَٱنظُرْ مَاذَا تَرَىٰ ۚ قَالَ يَٰٓأَبَتِ ٱفْعَلْ مَا تُؤْمَرُ ۖ سَتَجِدُنِىٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ} <strong>(سورة الصافات ٣٧، الآية ١٠٢)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>أما في الصورة فلأنه كان ولده أزيد من ثلاثة عشر سنة، وأم أنه وحيد في المعنى فإنه هو الذي هاجر به أبوه ومعه أمه هاجر، وكان صغيرا رضيعا فيما قيل، فوضعهما في وهاد جبال فاران، وهي الجبال التي حول مكة، نعم المقيل، وتركهما هنالك ليس معهما من الزاد والماء إلا القليل، وذلك ثقة بالله وتوكلا عليه، فحاطهما الله تعالى بعنايته وكفايته، فنعم الحسيب والكافي والوكيل والكفيل.</p>
<p>فهذا هو الولد الوحيد في الصورة والمعنى، ولكن أين من يتفطن لهذا السر، وأين من يحل بهذا المحل، والمعنى لا يدركه ويحيط بعلمه إلا كل نبيه نبيل.</p>
<p>وقد أثنى الله تعالى عليه فوصفه بالحلم والصبر وصدق الوعد والمحافظة على الصلاة والأمر بها لأهله، ليقيهم العذاب مع ما كان يدعو إليه من عبادة رب الأرباب. قال الله تعالى: {فبشرناه بغلام حليم، فلما بلغ معه السعي قال يا بني إني أرى في المنام أني أذبحك فانظر ماذا ترى قال يا أبت افعل ما تؤمر ستجدني إن شاء الله من الصابرين} فطاوع أباه على ما إليه دعاه، ووعده بأن سيصبر فوفى بذلك وصبر على ذلك.</p>
<p>وقال تعالى: {واذكر في الكتاب إسماعيل إنه كان صادق الوعد وكان رسولا نبيا، وكان يأمر أهله بالصلاة والزكاة وكان عند ربه مرضيا}. وقال تعالى: {واذكر عبادنا إبراهيم وإسحاق ويعقوب أولي الأيدي والأبصار، إنا أخلصناهم بخالصة ذكرى الدار، وإنهم عندنا لمن المصطفين الأخيار} وقال تعالى: {وإسماعيل وإدريس وذا الكفل كل من الصابرين، وأدخلناهم في رحمتنا إنهم من الصالحين} وقال تعالى: {إنا أوحينا إليك كما أوحينا إلى نوح والنبيين من بعده وأوحينا إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط} الآية.</p>
<p>وقال تعالى: {قولوا آمنا بالله وما أنزل إلينا وما أنزل إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط} الآية. ونظيرتها من السورة الأخرى. وقال تعالى: {أم تقولون إن إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط كانوا هودا أو نصارى قل أأنتم أعلم أم الله}. الآية.</p>
<p>فذكر الله عنه كل صفة جميلة وجعله نبيه ورسوله، وبرأه من كل ما نسب إليه الجاهلون. وأمر بأن يؤمن بما أنزل عليه عباده المؤمنون.</p>
<p>وذكر علماء النسب وأيام الناس: أنه أول من ركب الخيل وكانت قبل ذلك وحوشا فأنسها وركبها. وقد قال سعيد بن يحيى الأموي في مغازيه حدثنا شيخ من قريش، حدثنا عبد الملك بن عبد العزيز، عن عبد الله بن عمر أن رسول الله صلى الله عليه وسلم قال: "اتخذوا الخيل واعتقبوها فإنها ميراث أبيكم إسماعيل".</p>
<p>وكانت هذه العراب وحوشا فدعا لها بدعوته التي كان أعطي فأجابته. وإنه أول من تكلم بالعربية الفصيحة البليغة، وكان قد تعلمها من العرب العاربة الذين نزلوا عندهم بمكة من جرهم، والعماليق وأهل اليمن من الأمم المتقدمين من العرب قبل الخليل.</p>
<p>قال الأموي: حدثني علي بن المغيرة، حدثنا أبو عبيدة، مسمع ابن مالك عن محمد بن علي بن الحسين، عن آبائه عن النبي صلى الله عليه وسلم أنه قال: "أول من فتق لسانه بالعربية البينة إسماعيل وهو ابن أربع عشرة سنة"، فقال له يونس: صدقت يا أبا سيار، هكذا أبو جرى حدثني.</p>
<blockquote>البابُ في الكتاب: ذكر إسماعيل عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%B0%D9%83%D8%B1_%D8%A5%D8%B3%D9%85%D8%A7%D8%B9%D9%8A%D9%84_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — ذكر إسماعيل عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: إسحاقُ عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%B0%D9%83%D8%B1_%D8%A5%D8%B3%D9%85%D8%A7%D8%B9%D9%8A%D9%84_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84',
  '["إسماعيل عليه السلام","قصص الأنبياء","ابن كثير"]'::jsonb,
  '{"القصّة":"٩ من ٢٥","الكتاب":"قصص الأنبياء — ابن كثير (جزؤه الأول)","الباب":"ذكر إسماعيل عليه السلام","الرخصة":"ويكي مصدر — رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)"}'::jsonb,
  'published', 170,
