-- ١٠) القصّةُ العاشرة: إسحاقُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-ishaq',
  'القصّةُ العاشرة: إسحاقُ عليه السلام',
  'قد قدمنا أنه ولد ولأبيه مائة سنة، بعد أخيه إسماعيل بأربع عشر سنة، وكان عمر أمه سارة حين بشرت به تسعين…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَٱمْرَأَتُهُۥ قَآئِمَةٌۭ فَضَحِكَتْ فَبَشَّرْنَٰهَا بِإِسْحَٰقَ وَمِن وَرَآءِ إِسْحَٰقَ يَعْقُوبَ} <strong>(سورة هود ١١، الآية ٧١)</strong></p>
<p>{وَبَشَّرْنَٰهُ بِإِسْحَٰقَ نَبِيًّۭا مِّنَ ٱلصَّٰلِحِينَ} <strong>(سورة الصافات ٣٧، الآية ١١٢)</strong></p>
<p>{فَأَوْجَسَ مِنْهُمْ خِيفَةًۭ ۖ قَالُوا۟ لَا تَخَفْ ۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٍۢ} <strong>(سورة الذاريات ٥١، الآية ٢٨)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قد قدمنا أنه ولد ولأبيه مائة سنة، بعد أخيه إسماعيل بأربع عشر سنة، وكان عمر أمه سارة حين بشرت به تسعين سنة.</p>
<p>قال الله تعالى: {وبشرناه بإسحاق نبيا من الصالحين، وباركنا عليه وعلى إسحاق ومن ذريتهما محسن وظالم لنفسه مبين}.</p>
<p>وقد ذكر الله تعالى بالثناء عليه في غير ما آية من كتابه العزيز.</p>
<p>وقدمنا في حديث أبي هريرة عن رسول الله صلى الله عليه وسلم "أن الكريم بن الكريم بن الكريم بن الكريم يوسف بن يعقوب بن إسحاق بن إبراهيم".</p>
<p>وذكر أهل الكتاب: أن اسحاق لما تزوج رفقا بنت بتواييل في حياة أبيه كان عمره أربعين سنة، وأنها كانت عاقرا فدعا الله لها فحملت، فولدت غلامين توأمين أولهما اسمه (عيصو) وهو الذي تسميه العرب العيص، وهو والد الروم. والثاني خرج وهو آخذ بعقب أخيه فسموه "يعقوب" وهو إسرائيل الذي ينتسب إليه بنو إسرائيل.</p>
<p>قالوا: وكان إسحاق يحب عيصو أكثر من يعقوب، لأنه بكره، وكانت أمهما رفقا تحب يعقوب أكثر لأنه الأصغر.</p>
<p>قالوا: فلما كبر إسحاق وضعف بصره اشتهى على ابنه العيص طعاما، وأمره أن يذهب فيصطاد له صيدا، ويطبخه له ليبارك عليه ويدعو له، وكان العيص صاحب صيد فذهب يبتغي ذلك، فأمرت رفقا ابنها يعقوب أن يذبح جديين من خيار غنمه ويصنع منهما طعاما كما اشتهاه أبوه، ويأتي إليه به قبل أخيه، ليدعو لهن فقامت فألبسته ثياب أخيه، وجعلت على ذراعيه وعنقه من جلد الجديين، لأن العيص كان أشعر الجسد، ويعقوب ليس كذلك، فلما جاء به وقربه إليه قال: من أنت قال: ولدك، فضمه إليه وجسه وجعل يقول: أما الصوت فصوت يعقوب، وأما الجس والثياب فالعيص، فلما أكل وفرغ دعا له أن يكون أكبر إخوته قدرا، وكلمته عليهم وعلى الشعوب بعده، وأن يكثر رزقه وولده.</p>
<p>فلما خرج من عنده جاء أخوه العيص بما أمره به والده فقربه إليه، فقال له: ما هذا يا بني؟ قال: هذا الطعام الذي اشتهيته. فقال: أما جئتني به قبل الساعة وأكلت منه ودعوت لك؟ فقال: لا والله. وعرف أن أخاه قد سبقه إلى ذلك، فوجد في نفسه عليه وجدا كثيرا. وذكروا أنه تواعده بالقتل إذا مات أبوهما، وسأل أباه فدعا له بدعوة أخرى، وأن يجعل لذريته غليظ الأرض، وأن يكثر أرزاقهم وثمارهم.</p>
<p>فلما سمعت أمهما ما يتواعد به العيص أخاه يعقوب، أمرت ابنها يعقوب أن يذهب إلى أخيها "لابان" الذي بأرض حران، وأن يكون عنده إلى حين يسكن غضب أخيه، وأن يتزوج من بناته، وقالت لزوجها إسحاق أن يأمره بذلك ويوصيه ويدعو له ففعل.</p>
<p>فخرج يعقوب عليه السلام من عندهم من آخر ذلك اليوم، فأدركه المساء في موضع، فنام فيه، وأخذ حجرا فوضعه تحت رأسه ونام، فرأى في نومه ذلك معراجا منصوبا من السماء إلى الأرض وإذا الملائكة يصعدون فيه وينزلون، والرب تبارك وتعالى يخاطبه، ويقول له: إني سأبارك عليك، وأكثر ذريتك، وأجعل لك هذه الأرض ولعقبك من بعدك.</p>
<p>فلما هب من نومه فرح بما رأى، ونذر لله لئن رجع إلى أهله سالما ليبنين في هذا الموضع معبدا لله عز وجل، وأن جميع ما يرزقه من شيء يكون لله عشره.</p>
<p>ثم عمد إلى ذلك الحجر فجعل عليه دهنا يتعرفه به، وسمي ذلك الموضع (بيت إيل) أي بيت الله وهو موضع بيت المقدس اليوم الذي بناه يعقوب بعد ذلك كما سيأتي.</p>
<blockquote>البابُ في الكتاب: ذكر إسحاق بن إبراهيم الكريم بن الكريم عليهما الصلاة والتسليم — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%B0%D9%83%D8%B1_%D8%A5%D8%B3%D8%AD%D8%A7%D9%82_%D8%A8%D9%86_%D8%A5%D8%A8%D8%B1%D8%A7%D9%87%D9%8A%D9%85_%D8%A7%D9%84%D9%83%D8%B1%D9%8A%D9%85_%D8%A8%D9%86_%D8%A7%D9%84%D9%83%D8%B1%D9%8A%D9%85_%D8%B9%D9%84%D9%8A%D9%87%D9%85%D8%A7_%D8%A7%D9%84%D8%B5%D9%84%D8%A7%D8%A9_%D9%88%D8%A7%D9%84%D8%AA%D8%B3%D9%84%D9%8A%D9%85">قصصُ الأنبياء لابن كثير — ذكر إسحاق بن إبراهيم الكريم بن الكريم عليهما الصلاة والتسليم</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: يعقوبُ إسرائيل عليه السلام.</p>',
