-- ١١) القصّةُ الحادية عشرة: يعقوبُ إسرائيل عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-yaqub',
  'القصّةُ الحادية عشرة: يعقوبُ إسرائيل عليه السلام',
  'فخرج يعقوب عليه السلام من عندهم من آخر ذلك اليوم، فأدركه المساء في موضع، فنام فيه، وأخذ حجرا فوضعه تحت رأسه ونام، فرأى في نومه ذلك معراجا منصوبا من…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{قَالَ إِنَّمَآ أَشْكُوا۟ بَثِّى وَحُزْنِىٓ إِلَى ٱللَّهِ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ} <strong>(سورة يوسف ١٢، الآية ٨٦)</strong></p>
<p>{وَوَصَّىٰ بِهَآ إِبْرَٰهِۦمُ بَنِيهِ وَيَعْقُوبُ يَٰبَنِىَّ إِنَّ ٱللَّهَ ٱصْطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ} <strong>(سورة البقرة ٢، الآية ١٣٢)</strong></p>
<p>{۞ كُلُّ ٱلطَّعَامِ كَانَ حِلًّۭا لِّبَنِىٓ إِسْرَٰٓءِيلَ إِلَّا مَا حَرَّمَ إِسْرَٰٓءِيلُ عَلَىٰ نَفْسِهِۦ مِن قَبْلِ أَن تُنَزَّلَ ٱلتَّوْرَىٰةُ ۗ قُلْ فَأْتُوا۟ بِٱلتَّوْرَىٰةِ فَٱتْلُوهَآ إِن كُنتُمْ صَٰدِقِينَ} <strong>(سورة آل عمران ٣، الآية ٩٣)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>فخرج يعقوب عليه السلام من عندهم من آخر ذلك اليوم، فأدركه المساء في موضع، فنام فيه، وأخذ حجرا فوضعه تحت رأسه ونام، فرأى في نومه ذلك معراجا منصوبا من السماء إلى الأرض وإذا الملائكة يصعدون فيه وينزلون، والرب تبارك وتعالى يخاطبه، ويقول له: إني سأبارك عليك، وأكثر ذريتك، وأجعل لك هذه الأرض ولعقبك من بعدك.</p>
<p>فلما هب من نومه فرح بما رأى، ونذر لله لئن رجع إلى أهله سالما ليبنين في هذا الموضع معبدا لله عز وجل، وأن جميع ما يرزقه من شيء يكون لله عشره.</p>
<p>ثم عمد إلى ذلك الحجر فجعل عليه دهنا يتعرفه به، وسمي ذلك الموضع (بيت إيل) أي بيت الله وهو موضع بيت المقدس اليوم الذي بناه يعقوب بعد ذلك كما سيأتي.</p>
<p>قالوا: فما قدم يعقوب على خاله أرض حران إذا له ابنتان اسم الكبرى "ليا" واسم الصغرى "راحيل" وكانت أحسنهما وأجملهما فطلب يعقوب الصغرى من خاله، فأجابه إلى ذلك بشرط أن يرعى على غنمه سبع سنين، فلما مضت المدة على خاله "لابان"، صنع طعاما وجمع الناس عليه، وزف إليه ابنته الكبرى "ليا"، وكانت ضعيفة العينين قبيحة المنظر. فلما أصبح يعقوب إذا هي "ليا"، فقال لخاله: لم غدرت بي، وأنت إنما خطبت إليك راحيل؟. فقال: إنه ليس من سنتنا أن نزوج الصغرى قبل الكبرى، فإن أحببت أختها فاعمل سبع سنين أخرى، وأزوجكها.</p>
<p>فعمل سبع سنين وأدخلها عليه مع أختها وكان ذلك سائغا في ملتهم. ثم نسخ في شريعة التوراة. وهذا وحده دليل كاف على وقوع النسخ لأن فعل يعقوب عليه السلام دليل على جواز هذا وإباحته لأنه معصوم. ووهب "لابان" لكل واحدة من ابنتيه جارية فوهب لليا جارية اسمها "زلفى"، ووهب لراحيل جارية اسمها "بلهى".</p>
<p>وجبر الله تعالى ضعف "ليا" بأن وهب لها أولادا، فكان أول من ولدت ليعقوب روبيل، ثم شمعون، ثم لاوي، ثم يهوذا، فغارت عند ذلك "راحيل"، وكانت لا تحبل، فوهبت ليعقوب جاريتها "بلهى" فوطئها فحملت وولدت له غلاما سمته "دان"، وحملت وولدت غلاما آخر سمته "نيفتالي" فعمدت عند ذلك "ليا" فوهبت جاريتها "زلفى" من يعقوب عليه السلام فولدت له جاد وأشير، غلامين ذكرين، ثم حملت "ليا" أيضا فولدت غلاما خامسا منها، وسمته "ايساخر". ثم حملت وولدت غلاما سادسا سمته "زابلون"، ثم حملت وولدت بنتا سمتها "دينار"، فصار لها سبعة من يعقوب.</p>
<p>ثم دعت الله تعالى "راحيل" وسألته أن يهب لها غلاما من يعقوب فسمع الله ندائها وأجاب دعائها فحملت من نبي الله يعقوب فولدت له غلاما عظيما شريفا حسنا جميلا سمته "يوسف".</p>
<p>كل هذا وهم مقيمون بأرض حران وهو يرعى على خاله غنمه بعد دخوله على البنتين ست سنين أخرى، فصار مدة مقامه عشرين سنة.</p>
<p>فطلب يعقوب من خاله لابان أن يسرحه ليمر إلى أهله، فقال له خاله: إني قد بورك لي بسببك، فسلني من مالي ما شئت؟ فقال: تعطيني كل حمل يولد من غنمك هذه السنة أبقع، وكل حمل ملمع ابيض بسواد، وكل أملح ببياض، وكل أجلح أبيض من المعز، فقال: نعم.</p>
<p>فعمد بنوه فابرزوا من غنم أبيهم ما كان على هذه الصفات من التيوس لئلا يولد شيء من الحملان على هذه الصفات وساروا بها مسيرة ثلاثة أيام عن غنم أبيهم.</p>
<blockquote>البابُ في الكتاب: ذكر إسحاق بن إبراهيم الكريم بن الكريم عليهما الصلاة والتسليم — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%B0%D9%83%D8%B1_%D8%A5%D8%B3%D8%AD%D8%A7%D9%82_%D8%A8%D9%86_%D8%A5%D8%A8%D8%B1%D8%A7%D9%87%D9%8A%D9%85_%D8%A7%D9%84%D9%83%D8%B1%D9%8A%D9%85_%D8%A8%D9%86_%D8%A7%D9%84%D9%83%D8%B1%D9%8A%D9%85_%D8%B9%D9%84%D9%8A%D9%87%D9%85%D8%A7_%D8%A7%D9%84%D8%B5%D9%84%D8%A7%D8%A9_%D9%88%D8%A7%D9%84%D8%AA%D8%B3%D9%84%D9%8A%D9%85">قصصُ الأنبياء لابن كثير — ذكر إسحاق بن إبراهيم الكريم بن الكريم عليهما الصلاة والتسليم</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: يوسفُ عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84',
  '["يعقوب إسرائيل عليه السلام","قصص الأنبياء","ابن كثير"]'::jsonb,
  '{"القصّة":"١١ من ٢٥","الكتاب":"قصص الأنبياء — ابن كثير (جزؤه الأول)","الباب":"ذكر إسحاق بن إبراهيم الكريم بن الكريم عليهما الصلاة والتسليم","الرخصة":"ويكي مصدر — رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)"}'::jsonb,
  'published', 150,
  '2026-10-22T00:00:00.000Z'::timestamptz
