-- ١٢) القصّةُ الثانية عشرة: يوسفُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-yusuf',
  'القصّةُ الثانية عشرة: يوسفُ عليه السلام',
  'قال تعالى {إذ قال يوسف لأبيه ياأبت إني رأيت أحد عشر كوكبا والشمس والقمر رأيتهم لي ساجدين، قال يا بني لا تقصص رؤياك على إخوتك فيكيدوا لك كيدا إن…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{إِذْ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّى رَأَيْتُ أَحَدَ عَشَرَ كَوْكَبًۭا وَٱلشَّمْسَ وَٱلْقَمَرَ رَأَيْتُهُمْ لِى سَٰجِدِينَ} <strong>(سورة يوسف ١٢، الآية ٤)</strong></p>
<p>{۞ وَمَآ أُبَرِّئُ نَفْسِىٓ ۚ إِنَّ ٱلنَّفْسَ لَأَمَّارَةٌۢ بِٱلسُّوٓءِ إِلَّا مَا رَحِمَ رَبِّىٓ ۚ إِنَّ رَبِّى غَفُورٌۭ رَّحِيمٌۭ} <strong>(سورة يوسف ١٢، الآية ٥٣)</strong></p>
<p>{قَالَ لَا تَثْرِيبَ عَلَيْكُمُ ٱلْيَوْمَ ۖ يَغْفِرُ ٱللَّهُ لَكُمْ ۖ وَهُوَ أَرْحَمُ ٱلرَّٰحِمِينَ} <strong>(سورة يوسف ١٢، الآية ٩٢)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قال تعالى {إذ قال يوسف لأبيه ياأبت إني رأيت أحد عشر كوكبا والشمس والقمر رأيتهم لي ساجدين، قال يا بني لا تقصص رؤياك على إخوتك فيكيدوا لك كيدا إن الشيطان للإنسان عدو مبين، وكذلك يجتبيك ربك ويعلمك من تأويل الأحاديث ويتم نعمته عليك وعلى آل يعقوب كما أتمها على أبويك من قبل إبراهيم وإسحاق إن ربك عليم حكيم}.</p>
<p>قد قدمنا أن يعقوب كان له من البنين اثنا عشر ولدا ذكرا وسميناهم، وإليهم تنسب أسباط بني إسرائيل كلهم، وكان أشرفهم وأجلهم وأعظمهم يوسف عليه السلام.</p>
<p>وقد ذهب طائفة من العلماء إلى أنه لم يكن فيهم نبي غيره، وباقي اخوته لم يوح إليهم.</p>
<p>وظاهر ما ذكر من فعالهم ومقالهم في هذه القصة يدل على هذا القول.</p>
<p>ومن استدل على نبوتهم بقوله: {قولوا آمنا بالله وما أنزل إلينا وما أنزل إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط} وزعم أن هؤلاء هم الأسباط، فليس استدلاله بقوى، لأن المراد بالأسباط شعوب بني إسرائيل وما كان يوجد فيهم من الأنبياء الذين ينزل عليهم الوحي من السماء والله أعلم.</p>
<p>ومما يؤيد أن يوسف عليه السلام هو المختص من بين اخوته بالرسالة والنبوة - أنه ما نص على واحد من اخوته سواه فدل على ما ذكرناه.</p>
<p>ويستأنس لهذا بما قال الإمام أحمد: حدثنا عبد الصمد، حدثنا عبد الرحمن، عن عبد الله بن دينار، عن أبيه، عن ابن عمر، أن رسول الله صلى الله عليه وسلم قال: "الكريم ابن الكريم ابن الكريم ابن الكريم يوسف بن يعقوب بن إسحاق بن إبراهيم".</p>
<p>انفرد به البخاري. فرواه عن عبد الله بن محمد وعبدة عن عبد الصمد بن عبد الوارث به وقد ذكرنا طرقه في قصة إبراهيم بما أغنى عن إعادته هنا. ولله الحمد والمنة.</p>
<p>قال المفسرون وغيرهم: رأى يوسف عليه السلام وهو صغير قبل أن يحتلم، كأن أحد عشر كوكبا، وهم إشارة إلى بقية إخوته، والشمس والقمر وهما عبارة عن أبويه، قد سجدوا له فهاله ذلك.</p>
<p>فلما استيقظ قصها على أبيه، فعرف أبوه أنه سينال منزلة عالية ورفعة عظيمة في الدنيا والآخرة، بحيث يخضع له أبواه وأخوته فيها. فأمره بكتمانها وألا يقصها على أخوته؛ كي لا يحسدوه ويبغوا له الغوائل ويكيدوه بأنواع الحيل والمكر. وهذا يدل على ما ذكرناه.</p>
<p>ولهذا جاء في بعض الآثار: "استعينوا على قضاء حوائجكم بكتمانها فإن كل ذي نعمة محسود".</p>
<p>{وكذلك يجتبيك ربك} أي وكما أراك هذه الرؤية العظيمة، فإذا كتمتها {يجتبيك ربك} أي يخصك بأنواع اللطف والرحمة، {ويعلمك من تأويل الأحاديث} أي يفهمك من معاني الكلام وتعبير المنام ما لا يفهمه غيرك.</p>
<p>{ويتم نعمته عليك} أي بالوحي إليك {وعلى آل يعقوب} أي بسببك، ويحصل لهم بك خير الدنيا والآخرة. {كما أتمها على أبويك من قبل إبراهيم وإسحاق} أي ينعم عليك ويحسن إليك بالنبوة، كما أعطاها أباك يعقوب، وجدك اسحاق، ووالد جدك إبراهيم الخليل، {إن ربك عليم حكيم}كما قال تعالى: {الله أعلم حيث يجعل رسالته}.</p>
<p>ولهذا قال رسول الله صلى الله عليه وسلم لما سئل أي الناس أكرم؟ قال: "يوسف نبي الله ابن نبي الله ابن نبي الله ابن خليل الله".</p>
<blockquote>البابُ في الكتاب: ذكر ما وقع من الأمور العجيبة في حياة إسرائيل فمن ذلك قصة يوسف بن راحيل — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D8%B0%D9%83%D8%B1_%D9%85%D8%A7_%D9%88%D9%82%D8%B9_%D9%85%D9%86_%D8%A7%D9%84%D8%A3%D9%85%D9%88%D8%B1_%D8%A7%D9%84%D8%B9%D8%AC%D9%8A%D8%A8%D8%A9_%D9%81%D9%8A_%D8%AD%D9%8A%D8%A7%D8%A9_%D8%A5%D8%B3%D8%B1%D8%A7%D8%A6%D9%8A%D9%84_%D9%81%D9%85%D9%86_%D8%B0%D9%84%D9%83_%D9%82%D8%B5%D8%A9_%D9%8A%D9%88%D8%B3%D9%81_%D8%A8%D9%86_%D8%B1%D8%A7%D8%AD%D9%8A%D9%84_2">قصصُ الأنبياء لابن كثير — ذكر ما وقع من الأمور العجيبة في حياة إسرائيل فمن ذلك قصة يوسف بن راحيل</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: أيوبُ عليه السلام.</p>',
