-- ١٣) القصّةُ الثالثة عشرة: أيوبُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-ayyub',
  'القصّةُ الثالثة عشرة: أيوبُ عليه السلام',
  'قال علماء التفسير والتاريخ وغيرهم: كان أيوب رجلا كثير المال، من سائر صنوفه وأنواعه من الأنعام والعبيد والمواشي والأراضي المتسعة بأرض الثنية من أرض…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{۞ وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلضُّرُّ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ} <strong>(سورة الأنبياء ٢١، الآية ٨٣)</strong></p>
<p>{فَٱسْتَجَبْنَا لَهُۥ فَكَشَفْنَا مَا بِهِۦ مِن ضُرٍّۢ ۖ وَءَاتَيْنَٰهُ أَهْلَهُۥ وَمِثْلَهُم مَّعَهُمْ رَحْمَةًۭ مِّنْ عِندِنَا وَذِكْرَىٰ لِلْعَٰبِدِينَ} <strong>(سورة الأنبياء ٢١، الآية ٨٤)</strong></p>
<p>{وَٱذْكُرْ عَبْدَنَآ أَيُّوبَ إِذْ نَادَىٰ رَبَّهُۥٓ أَنِّى مَسَّنِىَ ٱلشَّيْطَٰنُ بِنُصْبٍۢ وَعَذَابٍ} <strong>(سورة صٓ ٣٨، الآية ٤١)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قال علماء التفسير والتاريخ وغيرهم: كان أيوب رجلا كثير المال، من سائر صنوفه وأنواعه من الأنعام والعبيد والمواشي والأراضي المتسعة بأرض الثنية من أرض حوران.وحكى ابن عساكر: أنها كلها كانت له، وكان له أولاد وأهلون كثير.</p>
<p>فسلب منه ذلك جميعه، وابتلي في جسده بأنواع من البلاء، ولم يبق منه عضو سليم سوى قلبه ولسانه. يذكر الله عز وجل بهما وهو في ذلك كله صابر محتسب ذاكر لله عز وجل في ليله ونهاره وصباحه ومسائه.</p>
<p>وطال مرضه حتى عافه الجليس وأوحش منه الأنيس، وأخرج من بلده، وألقي على مزبلة خارجها، وانقطع عنه الناس، ولم يبق أحد يحنو عليه سوى زوجته، كانت ترعى له حقه وتعرف قديم إحسانه إليها وشفقته عليها، فكانت تتردد إليه فتصلح من شأنه وتعينه على قضاء حاجته وتقوم بمصلحته. وضعف حالها، وقل ما لها حتى كانت تخدم الناس بالأجر لتطعمه، وتقوم بأوده رضي الله عنها وأرضاها، وهي صابرة معه على ما حل بهما من فراق المال والولد وما يختص بها من المصيبة بالزوج، وضيق ذات اليد وخدمة الناس بعد السعادة والنعمة والخدمة والحرمة، فإنا لله وإنا إليه راجعون!.</p>
<p>وقد ثبت في الصحيح، أن رسول الله صلى الله عليه وسلم قال: "أشد الناس بلاء الأنبياء. ثم الصالحون. ثم الأمثل فالأمثل"، وقال: "يبتلي الرجل على حسب دينه، فإن كان في دينه صلابة زيد في بلائه".</p>
<p>وقد ثبت في الصحيح أن رسول الله صلى الله عليه وسلم قال: "أشد حتى أن المثل ليضرب بصبره عليه السلام، ويضرب المثل أيضا بما حصل له من أنواع البلايا.</p>
<p>وقد روي عن وهب بن منبه وغيره من علماء بني إسرائيل في قصة أيوب خبر طويل في كيفية ذهاب ماله وولده وبلائه في جسده والله أعلم بصحته.</p>
<p>وقد اختلفوا في مدة بلواه على أقوال فزعم وهب: أنه ابتلي سنين لا تزيد ولا تنقص. وقال أنس: ابتلى سبع سنين وأشهرا، وألقي على مزبلة لبني إسرائيل، تختلف الدواب في جسده حتى فرج الله عنه، وأعظم له الأجر، وأحسن الثناء عليه. وقال حميد: مكث في بلواه ثمانية عشرة سنة.</p>
<p>وقال السدي: تساقط لحمه حتى لم يبق إلا العظم والعصب. فكانت امرأته تأتيه بالرماد تفرشه تحته فلما طال عليها، قالت: "يا أيوب لو دعوت ربك لفرج عنك فقال قد عشت سبعين سنة صحيحا فهو قليل لله أن أصبر له سبعين سنة". فجزعت من هذا الكلام وكانت تخدم الناس بالأجر وتطعم أيوب عليه السلام.</p>
<p>ثم إن الناس لم يكونوا يستخدمونها، لعلمهم أنها امرأة أيوب، خوفا أن ينالهم من بلائه، أو تعديهم بمخالطته، فلما لم تجد أحدا يستخدمها عمدت فباعت لبعض بنات الأشراف إحدى ضفيرتيها بطعام طيب كثير، فأتت به أيوب، فقال: من أين لك هذا؟ وأنكره، فقالت: خدمت به أناسا، فلما كان الغد لم تجد أحدا، فباعت الضفيرة الأخرى بطعام فأتته به فأنكره أيضا، وحلف لا يأكله حتى تخبره من أين لها هذا الطعام؟ فكشفت عن رأسها خمارها، فلما رأى رأسها محلوقا، قال في دعائه: "رب إني مسني الضر وأنت أرحم الراحمين".</p>
<blockquote>البابُ في الكتاب: قصة أيوب عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D8%A3%D9%8A%D9%88%D8%A8_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة أيوب عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: ذو الكفل عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D8%A3%D9%8A%D9%88%D8%A8_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84',
