-- ١٤) القصّةُ الرابعة عشرة: ذو الكفل عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-dhul-kifl',
  'القصّةُ الرابعة عشرة: ذو الكفل عليه السلام',
  'فالظاهر من ذكره في القرآن العظيم بالثناء عليه مقرونا مع هؤلاء السادة الأنبياء أنه نبي عليه من ربه الصلاة والسلام وهذا هو…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَإِسْمَٰعِيلَ وَإِدْرِيسَ وَذَا ٱلْكِفْلِ ۖ كُلٌّۭ مِّنَ ٱلصَّٰبِرِينَ} <strong>(سورة الأنبياء ٢١، الآية ٨٥)</strong></p>
<p>{وَأَدْخَلْنَٰهُمْ فِى رَحْمَتِنَآ ۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ} <strong>(سورة الأنبياء ٢١، الآية ٨٦)</strong></p>
<p>{وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ ۖ وَكُلٌّۭ مِّنَ ٱلْأَخْيَارِ} <strong>(سورة صٓ ٣٨، الآية ٤٨)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>فالظاهر من ذكره في القرآن العظيم بالثناء عليه مقرونا مع هؤلاء السادة الأنبياء أنه نبي عليه من ربه الصلاة والسلام وهذا هو المشهور.</p>
<p>وقد زعم آخرون أنه لم يكن نبيا وإنما كان رجلا صالحا وحكما مقسطا عادلا. وتوقف ابن جرير في ذلك فالله أعلم.</p>
<p>وروى ابن جرير وأبو نجيح عن مجاهد أنه لم يكن نبيا، وإنما كان رجلا صالحا.</p>
<p>وكان قد تكفل لبني قومه أن يكفيهم أمرهم، ويقضي بينهم بالعدل فيفعل فسمي ذا الكفل.</p>
<p>وروى ابن جرير وابن أبي حاتم من طريق داود بن أبي هند عن مجاهد أنه قال: لما كبر اليسع قال لو أني استخلفت رجلا على الناس يعمل عليهم في حياتي حتى أنظر كيف يعمل؟ فجمع الناس فقال: من يتقبل لي بثلاث استخلفه: يصوم النهار، ويقوم الليل، ولا يغضب.</p>
<p>قال: فقام رجل تزدريه العين، فقال: أنا، فقال: أنت تصوم النهار، وتقوم الليل، ولا تغضب؟ قال: نعم. قال: فردهم ذلك اليوم، وقال مثلها اليوم الآخر، فسكت الناس وقام ذلك الرجل فقال أنا، فاستخلفه.</p>
<p>قال: فجعل إبليس يقول للشياطين: عليكم بفلان، فأعياهم ذلك. فقال دعوني وإياه فاتاه في صورة شيخ كبير فقير، وأتاه حين اخذ مضجعه للقائلة، وكان لا ينام الليل والنهار، إلا تلك النومة فدق الباب. فقال: من هذا؟ قال: شيخ كبير مظلوم. قال: فقام ففتح الباب فجعل يقص عليه، فقال إن بيني وبين قومي خصومة، وإنهم ظلموني وفعلوا بي وفعلوا وجعل يطول عليه حتى حضر الرواح، وذهبت القائلة. وقال: إذا رحت فإنني آخذ لك بحقك.</p>
<p>فانطلق وراح. فكان في مجلسه فجعل ينظر هل يرى الشيخ، فلم يره، فقام يتبعه، فلما كان الغد جعل يقضي بين الناس وينتظره فلا يراه. فلما رجع إلى القائلة فأخذ مضجعه، أتاه فدق الباب، فقال: من هذا؟ فقال الشيخ الكبير المظلوم. ففتح له فقال: ألم أقل لك إذا قعدت فاتني؟ فقال: إنهم اخبث قوم إذا عرفوا انك قاعد، قالوا: نحن نعطيك حقك، وإذا قمت جحدوني. قال: فانطلق فإذا رحت فأتني.</p>
<p>قال: ففاتته القائلة، فراح فجعل ينتظر فلا يراه وشق عليه النعاس، فقال لبعض أهله: لا تدعن أحدا يقرب هذا الباب حتى أنام، فإني قد شق علي النوم. فلما كان تلك الساعة جاء فقال له الرجل وراءك وراءك، فقال: قد أتيته أمس، فذكرت له أمري، فقال: لا والله لقد أمرنا أن لا ندع أحدا يقربه، فلما أعياه نظر فرأى كوة في البيت فتسور منها فإذا هو في البيت، وإذا هو يدق الباب من داخل، قال فاستيقظ الرجل، فقال: يا فلان ألم آمرك؟ قال: أما من قبلي والله فلم تؤت، فانظر من أين أتيت؟</p>
<p>قال: فقام إلى الباب فإذا هو مغلق كما أغلقه؟ وإذا الرجل معه في البيت، فعرفه فقال: أعدو الله؟ قال: نعم أعييتني في كل شيء ففعلت كل ما ترى لأغضبك.</p>
<p>وقد روى ابن أبي حاتم أيضا عن ابن عباس قريبا من هذا السياق وهكذا روى عن عبد الله بن الحارث ومحمد بن قيس وابن حجيرة الأكبر، وغيرهم من السلف نحو هذا.</p>
<blockquote>البابُ في الكتاب: قصة ذي الكفل الذي زعم قوم أنه ابن أيوب — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D8%B0%D9%8A_%D8%A7%D9%84%D9%83%D9%81%D9%84_%D8%A7%D9%84%D8%B0%D9%8A_%D8%B2%D8%B9%D9%85_%D9%82%D9%88%D9%85_%D8%A3%D9%86%D9%87_%D8%A7%D8%A8%D9%86_%D8%A3%D9%8A%D9%88%D8%A8">قصصُ الأنبياء لابن كثير — قصة ذي الكفل الذي زعم قوم أنه ابن أيوب</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: يونسُ عليه السلام.</p>',
