-- ١٥) القصّةُ الخامسة عشرة: يونسُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-yunus',
  'القصّةُ الخامسة عشرة: يونسُ عليه السلام',
  'قال أهل التفسير: بعث الله يونس عليه السلام إلى أهل (نينوى) من أرض الموصل، فدعاهم إلى الله عز وجل، فكذبوه وتمردوا على كفرهم وعنادهم، فلما طال ذلك عليه…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{فَلَوْلَا كَانَتْ قَرْيَةٌ ءَامَنَتْ فَنَفَعَهَآ إِيمَٰنُهَآ إِلَّا قَوْمَ يُونُسَ لَمَّآ ءَامَنُوا۟ كَشَفْنَا عَنْهُمْ عَذَابَ ٱلْخِزْىِ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَمَتَّعْنَٰهُمْ إِلَىٰ حِينٍۢ} <strong>(سورة يونس ١٠، الآية ٩٨)</strong></p>
<p>{وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبًۭا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ فَنَادَىٰ فِى ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبْحَٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّٰلِمِينَ} <strong>(سورة الأنبياء ٢١، الآية ٨٧)</strong></p>
<p>{فَٱلْتَقَمَهُ ٱلْحُوتُ وَهُوَ مُلِيمٌۭ} <strong>(سورة الصافات ٣٧، الآية ١٤٢)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قال أهل التفسير: بعث الله يونس عليه السلام إلى أهل (نينوى) من أرض الموصل، فدعاهم إلى الله عز وجل، فكذبوه وتمردوا على كفرهم وعنادهم، فلما طال ذلك عليه من أمرهم، خرج من بين أظهرهم ووعدهم حلول العذاب بهم بعد ثلاث.</p>
<p>قال ابن مسعود ومجاهد وسعيد بن جبير وقتادة وغير واحد من السلف والخلف: فلما خرج من بين ظهرانيهم وتحققوا نزول العذاب بهم قذف الله في قلوبهم التوبة والإنابة وندموا على ما كان منهم إلى نبيهم، فلبسوا المسوح وفرقوا بين كل بهيمة وولدها ثم عجوا إلى الله عز وجل وصرخوا وتضرعوا إليه وتمسكنوا لديه، وبكى الرجال والنساء والبنون والبنات والأمهات، وجأرت الإنعام والدواب والمواشي، فرغت الأبل وفصلانها، وخارت البقر وأولادها، وثغت الغنم وحملانها، وكانت ساعة عظيمة هائلة.</p>
<p>فكشف الله العظيم بحوله وقوته ورأفته ورحمته عنهم العذاب الذي كان قد اتصل بهم سببه، ودار على رؤوسهم كقطع الليل المظلم.</p>
<p>ولهذا قال تعالى {فلولا كانت قرية آمنت فنفعها إيمانها} أي هلا وجدت فيما سلف من القرون قرية آمنت بكمالها فدل على أنه لم يقع ذلك. بل كما قال تعالى {وما أرسلنا في قرية من نذير إلا قال مترفوها إنا بما أرسلتم به كافرون}. وقوله {إلا قوم يونس لما آمنوا كشفنا عنهم عذاب الخزي في الحياة الدنيا ومتعناهم إلى حين} أي آمنوا بكمالهم.</p>
<p>وقد اختلف المفسرون هل ينفعهم هذا الإيمان في الدار الآخرة فينقذهم من العذاب الأخروي كما أنقذهم من العذاب الدنيوي؟ على قولين:</p>
<p>الأظهر من السياق: نعم. والله أعلم، كما قال تعالى: {لما آمنوا} وقال تعالى: {وأرسلناه إلى مائة ألف أو يزيدون، فآمنوا فمتعناهم إلى حين}، وهذا المتاع إلى حين لا ينفي أن يكون معه غيره من رفع العذاب الأخروي والله أعلم.</p>
<p>وقد كانوا مائة ألف لا محالة، واختلفوا في الزيادة فعن مكحول عشرة آلاف. وروى الترمذي وابن جرير وابن أبي حاتم من حديث زهير عمن سمع أبا العالية: حدثني أبي بن كعب أنه سأل رسول الله صلى الله عليه وسلم عن قوله {وأرسلناه إلى مائة ألف أو يزيدون} قال يزيدون عشرين ألفا، فلولا هذا الرجل المبهم، لكان هذا الحديث فاصلا في هذا الباب.</p>
<p>وعن ابن عباس كانوا مائة ألف وثلاثين ألفا، وعنه وبضعة وثلاثين ألفا. وعنه وبضعة وأربعين ألفا. وقال سعيد بن جبير: كانوا مائة ألف وسبعين ألفا.</p>
<p>واختلفوا هل كان إرساله إليهم قبل الحوت أو بعده؟ أو هما أمتان؟ على ثلاثة أقوال هي مبسوطة في التفسير.</p>
<p>والمقصود أنه عليه السلام لما ذهب مغاضبا بسبب قومه ركب سفينة في البحر فلجت بهم، واضطربت وماجت بهم وثقلت بما فيها، وكادوا يغرقون على ما ذكره المفسرون.</p>
<p>قالوا: فاشتوروا فيما بينهم، على أن يقترعوا، فمن وقعت عليه القرعة ألقوه من السفينة ليتخففوا منه.</p>
<p>فلما اقترعوا وقعت القرعة على نبي الله يونس، فلم يسمحوا به، فأعادوها ثانية فوقعت عليه أيضا، فشمر ليخلع ثيابه ويلقي بنفسه فأبوا عليه ذلك. ثم أعادوا القرعة ثالثة فوقعت عليه أيضا لما يريده الله به من الأمر العظيم.</p>
<blockquote>البابُ في الكتاب: قصة يونس عليه السلام — الجزءُ الأول، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D9%8A%D9%88%D9%86%D8%B3_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة يونس عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: موسى كليمُ الله عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84#%D9%82%D8%B5%D8%A9_%D9%8A%D9%88%D9%86%D8%B3_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%A3%D9%88%D9%84',
  '["يونس عليه السلام","قصص الأنبياء","ابن كثير"]'::jsonb,
  '{"القصّة":"١٥ من ٢٥","الكتاب":"قصص الأنبياء — ابن كثير (جزؤه الأول)","الباب":"قصة يونس عليه السلام","الرخصة":"ويكي مصدر — رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)"}'::jsonb,
