-- ١٦) القصّةُ السادسة عشرة: موسى كليمُ الله عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-musa',
  'القصّةُ السادسة عشرة: موسى كليمُ الله عليه السلام',
  'وكان الحامل له على هذا الصنيع القبيح أن بني إسرائيل كانوا يتدارسون فيما بينهم ما يأثرونه عن إبراهيم عليه السلام من أنه سيخرج من ذريته غلام يكون هلاك…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَهَلْ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ} <strong>(سورة طه ٢٠، الآية ٩)</strong></p>
<p>{إِنِّىٓ أَنَا۠ رَبُّكَ فَٱخْلَعْ نَعْلَيْكَ ۖ إِنَّكَ بِٱلْوَادِ ٱلْمُقَدَّسِ طُوًۭى} <strong>(سورة طه ٢٠، الآية ١٢)</strong></p>
<p>{وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ ۚ قَالَ لَن تَرَىٰنِى وَلَٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى ۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّۭا وَخَرَّ مُوسَىٰ صَعِقًۭا ۚ فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ} <strong>(سورة الأعراف ٧، الآية ١٤٣)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>وكان الحامل له على هذا الصنيع القبيح أن بني إسرائيل كانوا يتدارسون فيما بينهم ما يأثرونه عن إبراهيم عليه السلام من أنه سيخرج من ذريته غلام يكون هلاك ملك مصر على يديه وذلك - والله أعلم - حين كان جرى على سارة امرأة الخليل من ملك مصر من إرادته إياها على السوء وعصمة الله لها. وكانت هذه البشارة مشهورة في بني إسرائيل فتحدث بها القبط فيما بينهم ووصلت إلى فرعون فذكرها له بعض أمرائه وأساورته وهم يسمرون عنده فأمر عند ذلك بقتل أبناء بني إسرائيل حذرا من وجود هذا الغلام ولن يغني حذر من قدر.</p>
<p>وذكر السدي عن أبي صالح وأبي مالك عن ابن عباس وعن مرة عن ابن مسعود وعن أناس من الصحابة أن فرعون رأى في منامه كأن نارا قد أقبلت من نحو بيت المقدس فأحرقت دور مصر وجميع القبط ولم تضر بني إسرائيل. فلما استيقظ هاله ذلك فجمع الكهنة والحزقة والسحرة وسألهم عن ذلك؟ فقالوا: هذا غلام يولد من هؤلاء يكون سبب هلاك أهل مصر على يديه فلهذا أمر بقتل الغلمان وترك النسوان.</p>
<p>ولهذا قال الله تعالى: {ونريد أن نمن على الذين استضعفوا في الأرض} وهم بنو إسرائيل {ونجعلهم أئمة ونجعلهم الوارثين} أي الذين يؤول ملك مصر وبلادها إليهم {ونمكن لهم في الأرض ونري فرعون وهامان وجنودهما منهم ما كانوا يحذرون} أي سنجعل الضعيف قويا والمقهور قادرا والذليل عزيزا، وقد جرى هذا كله لبني إسرائيل كما قال تعالى: {وأورثنا القوم الذين كانوا يستضعفون مشارق الأرض ومغاربها التي باركنا فيها وتمت كلمة ربك الحسنى على بني إسرائيل بما صبروا} الآية. وقال تعالى: {فأخرجناهم من جنات وعيون، وكنوز ومقام كريم، كذلك وأورثناها بني إسرائيل} وسيأتي تفصيل ذلك في موضعه إن شاء الله.</p>
<p>والمقصود أن فرعون احترز كل الاحتراز أن لا يوجد موسى، حتى جعل رجالا وقوابل يدورون على الحبالى ويعلمون ميقات وضعهن، فلا تلد امرأة ذكرا إلا ذبحه أولئك الذباحون من ساعته.</p>
<p>وعند أهل الكتاب أنه إنما كان يأمر بقتل الغلمان لتضعف شوكة بني إسرائيل فلا يقاومونهم إذا غالبوهم أو قاتلوهم.</p>
<p>وهذا فيه نظر بل هو باطل، وإنما هذا في الأمر بقتل الولدان بعد بعثة موسى كما قال تعالى: {فلما جاءهم بالحق من عندنا قالوا اقتلوا أبناء الذين آمنوا معه واستحيوا نساءهم} ولهذا قالت بنو إسرائيل لموسى {أوذينا من قبل أن تأتينا ومن بعد ما جئتنا}.</p>
<p>فالصحيح أن فرعون إنما أمر بقتل الغلمان أولا حذرا من وجود موسى.</p>
<p>هذا، والقدر يقول: يا أيها ذا الملك الجبار المغرور بكثرة جنوده وسلطة بأسه واتساع سلطانه، قد حكم العظيم الذي لا يغالب ولا يمانع ولا تخالف أقداره، أن هذا المولود الذي تحترز منه، وقد قتلت بسببه من النفوس ما لا يعد ولا يحصى لا يكون مرباه إلا في دارك، وعلى فراشك ولا يغذى إلا بطعامك وشرابك في منزلك، وأنت الذي تتبناه وتربيه وتتفداه، ولا تطلع على سر معناه. ثم يكون هلاكك في دنياك وأخراك على يديه، لمخالفتك ما جاءك به من الحق المبين، وتكذيبك ما أوحى إليه، لتعلم أنت وسائر الخلق أن رب السماوات والأرض هو الفعال لما يريد وأنه هو القوي الشديد ذو البأس العظيم، والحول والقوة والمشيئة التي لا مرد لها.</p>
<blockquote>البابُ في الكتاب: ذكر قصة كليم الله موسى عليه السلام — الجزءُ الثاني، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D8%B0%D9%83%D8%B1_%D9%82%D8%B5%D8%A9_%D9%83%D9%84%D9%8A%D9%85_%D8%A7%D9%84%D9%84%D9%87_%D9%85%D9%88%D8%B3%D9%89_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — ذكر قصة كليم الله موسى عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: الخضرُ عليه السلام.</p>',
