-- ١٩) القصّةُ التاسعة عشرة: إلياسُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-ilyas',
  'القصّةُ التاسعة عشرة: إلياسُ عليه السلام',
  'قال علماء النسب هو: إلياس النشبي، ويقال: ابن ياسين بن فنحاص بن العيزار بن هارون وقيل: إلياس بن العازر بن العيزار بن هارون بن…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَإِنَّ إِلْيَاسَ لَمِنَ ٱلْمُرْسَلِينَ} <strong>(سورة الصافات ٣٧، الآية ١٢٣)</strong></p>
<p>{إِذْ قَالَ لِقَوْمِهِۦٓ أَلَا تَتَّقُونَ} <strong>(سورة الصافات ٣٧، الآية ١٢٤)</strong></p>
<p>{وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًۭا ۚ وَكُلًّۭا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ} <strong>(سورة الأنعام ٦، الآية ٨٦)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قال علماء النسب هو: إلياس النشبي، ويقال: ابن ياسين بن فنحاص بن العيزار بن هارون وقيل: إلياس بن العازر بن العيزار بن هارون بن عمران.</p>
<p>قالوا وكان إرساله إلى أهل بعلبك غربي دمشق، فدعاهم إلى الله عز وجل وأن يتركوا عبادة صنم لهم كانوا يسمونه "بعلا" وقيل كانت امرأة اسمها "بعل" والله أعلم.</p>
<p>والأول أصح ولهذا قال لهم: {ألا تتقون، أتدعون بعلا وتذرون أحسن الخالقين، الله ربكم ورب آبائكم الأولين}.</p>
<p>فكذبوه وخالفوه وأرادوا قتله. فيقال إنه هرب منهم، واختفى عنهم، قال أبو يعقوب الأذرعي، عن يزيد بن عبد الصمد، عن هشام بن عمار قال: وسمعت من يذكر عن كعب الأحبار أنه قال: إن إلياس اختفى من ملك قومه في الغار الذي تحت الدم عشر سنين، حتى أهلك الله الملك وولى غيره، فأتاه إلياس فعرض عليه الإسلام فأسلم، وأسلم من قومه خلق عظيم غير عشرة آلاف منهم. فأمر بهم فقتلوا عن آخرهم.</p>
<p>وقال ابن أبي الدنيا: حدثني أبو محمد القاسم بن هشام، حدثنا عمر بن سعيد الدمشقي، حدثنا سعيد بن عبد العزيز عن بعض مشيخة دمشق قال: أقام إلياس عليه السلام هاربا من قومه في كهف في جبل عشرين ليلة - أو قال أربعين ليلة تأتيه - الغربان برزقه.</p>
<p>وقال محمد بن سعد كاتب الواقدي: أنبأنا هشام بن محمد بن السائب الكلبي، عن أبيه قال: أول نبي بعث إدريس، ثم نوح، ثم إبراهيم، ثم إسماعيل وإسحاق، ثم يعقوب ثم يوسف ثم لوط ثم هود ثم صالح ثم شعيب، ثم موسى وهارون ابنا عمران، ثم إلياس النشبي بن العازر بن هارون بن عمران بن قاهث بن لاوى بن يعقوب بن إسحاق بن إبراهيم عليهم السلام. هكذا قال: وفي هذا الترتيب نظر. وقال مكحول عن كعب: أربعة أنبياء أحياء، اثنان في الأرض إلياس والخضر، واثنان في السماء: إدريس وعيسى عليهم السلام.</p>
<p>وقد قدمنا قول من ذكر أن إلياس والخضر يجتمعان في كل عام في شهر رمضان ببيت المقدس، وأنهما يحجان كل سنة ويشربان من زمزم شربة تكفيهما إلى مثلها من العام المقبل. وأوردنا الحديث الذي فيه أنهما يجتمعان بعرفات كل سنة.</p>
<p>وبينا أنه لم يصح شيء من ذلك، وأن الذي يقوم عليه الدليل: أن الخضر مات، وكذلك إلياس عليهما السلام.</p>
<p>وما ذكره وهب بن منبه وغيره: أنه لما دعا ربه عز وجل أن يقبضه إليه لما كذبوه وآذوه، فجاءته دابة لونها لون النار فركبها، وجعل الله له ريشا وألبسة النور، وقطع عنه لذة المطعم والمشرب وصار ملكيا بشريا سماويا أرضيا، وأوصى إلى اليسع بن أخطوب، ففي هذا نظر. وهو من الإسرائيليات التي لا تصدق ولا تكذب، بل الظاهر أن صحتها بعيدة، والله تعالى أعلم.</p>
<blockquote>البابُ في الكتاب: ذكر قصتي الخضر وإلياس عليهما السلام — الجزءُ الثاني، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D8%B0%D9%83%D8%B1_%D9%82%D8%B5%D8%AA%D9%8A_%D8%A7%D9%84%D8%AE%D8%B6%D8%B1_%D9%88%D8%A5%D9%84%D9%8A%D8%A7%D8%B3_%D8%B9%D9%84%D9%8A%D9%87%D9%85%D8%A7_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — ذكر قصتي الخضر وإلياس عليهما السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: اليسعُ عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D8%B0%D9%83%D8%B1_%D9%82%D8%B5%D8%AA%D9%8A_%D8%A7%D9%84%D8%AE%D8%B6%D8%B1_%D9%88%D8%A5%D9%84%D9%8A%D8%A7%D8%B3_%D8%B9%D9%84%D9%8A%D9%87%D9%85%D8%A7_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
