-- ٢٠) القصّةُ العشرون: اليسعُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-alyasa',
  'القصّةُ العشرون: اليسعُ عليه السلام',
  'قال ابن إسحاق: حدثنا بشر أبو حذيفة، أنبأنا سعيد، عن قتادة، عن الحسن، قال: كان بعد إلياس اليسع عليه السلام، فمكث ما شاء الله أن يمكث يدعوهم إلى الله…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَإِسْمَٰعِيلَ وَٱلْيَسَعَ وَيُونُسَ وَلُوطًۭا ۚ وَكُلًّۭا فَضَّلْنَا عَلَى ٱلْعَٰلَمِينَ} <strong>(سورة الأنعام ٦، الآية ٨٦)</strong></p>
<p>{وَٱذْكُرْ إِسْمَٰعِيلَ وَٱلْيَسَعَ وَذَا ٱلْكِفْلِ ۖ وَكُلٌّۭ مِّنَ ٱلْأَخْيَارِ} <strong>(سورة صٓ ٣٨، الآية ٤٨)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قال ابن إسحاق: حدثنا بشر أبو حذيفة، أنبأنا سعيد، عن قتادة، عن الحسن، قال: كان بعد إلياس اليسع عليه السلام، فمكث ما شاء الله أن يمكث يدعوهم إلى الله مستمسكا بمنهاج إلياس وشريعته حتى قبضه الله عز وجل إليه ثم خلف فيهم الخلوف وعظمت فيهم الأحداث والخطايا وكثرت الجبابرة وقتلوا الأنبياء، وكان فيهم ملك عنيد طاغ، ويقال إنه الذي تكفل له ذو الكفل إن هو تاب ورجع دخل الجنة فسمي ذا الكفل. قال محمد بن إسحاق هو اليسع بن أخطوب.</p>
<p>وقال الحافظ أبو القاسم ابن عساكر في حرف الياء من تاريخه: اليسع وهو الأسباط بن عدي بن شوتلم بن أفرايم بن يوسف بن يعقوب بن إسحاق بن إبراهيم الخليل. ويقال هو ابن عم إلياس النبي عليهما السلام ويقال كان مستخفيا معه بجبل قاسيون من ملك بعلبك ثم ذهب معه إليها، فلما رفع إلياس خلفه اليسع في قومه ونبأه الله بعده. ذكر ذلك عبد المنعم بن إدريس بن سنان عن أبيه، عن وهب بن منبه. قال وقال غيره وكان الأسباط ببانياش.</p>
<p>ثم ذكر ابن عساكر قراءة من قرأ اليسع بالتخفيف والتشديد ومن قرأ واليسع وهو اسم واحد لنبي من الأنبياء.</p>
<p>قلت: قد قدمنا قصة ذا الكفل بعد قصة أيوب عليه السلام لأنه قد قيل إنه ابن أيوب فالله تعالى أعلم.</p>
<blockquote>البابُ في الكتاب: قصة اليسع عليه السلام — الجزءُ الثاني، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D9%82%D8%B5%D8%A9_%D8%A7%D9%84%D9%8A%D8%B3%D8%B9_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة اليسع عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: داودُ عليه السلام.</p>',
