-- ٢١) القصّةُ الحادية والعشرون: داودُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-dawud',
  'القصّةُ الحادية والعشرون: داودُ عليه السلام',
  'تقدم أنه لما قتل جالوت وكان قتله له فيما ذكر ابن عساكر عند قصر أم حكيم بقرب مرج الصفر، فأحبته بنو إسرائيل ومالوا إليه وإلى ملكه عليهم، فكان من أمر…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{فَهَزَمُوهُم بِإِذْنِ ٱللَّهِ وَقَتَلَ دَاوُۥدُ جَالُوتَ وَءَاتَىٰهُ ٱللَّهُ ٱلْمُلْكَ وَٱلْحِكْمَةَ وَعَلَّمَهُۥ مِمَّا يَشَآءُ ۗ وَلَوْلَا دَفْعُ ٱللَّهِ ٱلنَّاسَ بَعْضَهُم بِبَعْضٍۢ لَّفَسَدَتِ ٱلْأَرْضُ وَلَٰكِنَّ ٱللَّهَ ذُو فَضْلٍ عَلَى ٱلْعَٰلَمِينَ} <strong>(سورة البقرة ٢، الآية ٢٥١)</strong></p>
<p>{ٱصْبِرْ عَلَىٰ مَا يَقُولُونَ وَٱذْكُرْ عَبْدَنَا دَاوُۥدَ ذَا ٱلْأَيْدِ ۖ إِنَّهُۥٓ أَوَّابٌ} <strong>(سورة صٓ ٣٨، الآية ١٧)</strong></p>
<p>{۞ وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ مِنَّا فَضْلًۭا ۖ يَٰجِبَالُ أَوِّبِى مَعَهُۥ وَٱلطَّيْرَ ۖ وَأَلَنَّا لَهُ ٱلْحَدِيدَ} <strong>(سورة سبإ ٣٤، الآية ١٠)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>تقدم أنه لما قتل جالوت وكان قتله له فيما ذكر ابن عساكر عند قصر أم حكيم بقرب مرج الصفر، فأحبته بنو إسرائيل ومالوا إليه وإلى ملكه عليهم، فكان من أمر طالوت ما كان وصار الملك إلى داود عليه السلام، وجمع الله له بين الملك والنبوة بين خير الدنيا والآخرة، وكان الملك يكون في سبط والنبوة في آخر فاجتمعا في داود هذا.</p>
<p>وهذا كما قال تعالى {وقتل داوود جالوت وآتاه الله الملك والحكمة وعلمه مما يشاء ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض ولكن الله ذو فضل على العالمين} أي لولا إقامة الملوك حكاما على الناس لأكل قوي الناس ضعيفهم. ولهذا جاء في بعض الآثار "السلطان ظل الله في أرضه". وقال أمير المؤمنين عثمان بن عفان: "إن الله ليزع بالسلطان ما لا يزع بالقرآن".</p>
<p>وقد ذكر ابن جرير في تاريخه أن جالوت لما بارز طالوت فقال له: اخرج إلي وأخرج إليك فندب طالوت الناس فانتدب داود فقتل جالوت.</p>
<p>قال وهب بن منبه: فمال الناس إلى داود حتى لم يكن لطالوت ذكر، وخلعوا طالوت وولوا عليهم داود. وقيل إن ذلك "كان" عن أمر شمويل حتى قال بعضهم إنه ولاه قبل الوقعة.</p>
<p>قال ابن جرير: والذي عليه الجمهور أنه إنما ولي ذلك بعد قتل جالوت والله أعلم. وروى ابن عساكر عن سعيد بن عبد العزيز أن قتله جالوت كان عند قصر أم حكيم، وأن النهر الذي هناك هو المذكور في الآية فالله أعلم.</p>
<p>وقال تعالى: {ولقد آتينا داوود منا فضلا يا جبال أوبي معه والطير وألنا له الحديد، أن اعمل سابغات وقدر في السرد واعملوا صالحا إني بما تعملون بصير} وقال تعالى: {وسخرنا مع داوود الجبال يسبحن والطير وكنا فاعلين، وعلمناه صنعة لبوس لكم لتحصنكم من بأسكم فهل أنتم شاكرون}.</p>
<p>أعانه الله على عمل الدروع من الحديد ليحصن المقاتلة من الأعداء وأرشده إلى صنعتها وكيفيتها فقال: {وقدر في السرد} أي لا تدق المسمار فيفلق ولا تغلظه فيفصم. قاله مجاهد وقتادة والحكم وعكرمة.</p>
<p>قال الحسن البصري وقتادة والأعمش: كان الله قد ألان له الحديد حتى كان يفتله بيده لا يحتاج إلى نار ولا مطرقة. قال قتادة: فكان أول من عمل الدروع من زرد وإنما كانت قبل ذلك من صفائح. قال ابن شوذب: كان يعمل كل يوم درعا يبيعها بستة آلاف درهم.</p>
<p>وقد ثبت في الحديث أن أطيب ما أكل الرجل من كسبه وأن نبي الله داود كان يأكل من كسب يده.</p>
<p>وقال تعالى: {واذكر عبدنا داوود ذا الأيد إنه أواب، إنا سخرنا الجبال معه يسبحن بالعشي والإشراق، والطير محشورة كل له أواب، وشددنا ملكه وآتيناه الحكمة وفصل الخطاب}.</p>
<p>قال ابن عباس ومجاهد: الأيد القوة في الطاعة. يعني ذا قوة في العبادة والعمل الصالح. قال قتادة: أعطي قوة في العبادة، وفقها في الإسلام، قال: وقد ذكر لنا أنه كان يقوم الليل ويصوم نصف الدهر.</p>
<p>وقد ثبت في الصحيحين أن رسول الله صلى الله عليه وسلم قال: "أحب الصلاة إلى الله صلاة داود، وأحب الصيام إلى الله صيام داود، كان ينام نصف الليل ويقوم ثلثه وينام سدسه، وكان يصوم يوما ويفطر يوما، ولا يفر إذا لاقى".</p>
<blockquote>البابُ في الكتاب: قصة داود عليه السلام وما كان في أيامه وذكر فضائله وشمائله ودلائل نبوته وأعلامه — الجزءُ الثاني، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D9%82%D8%B5%D8%A9_%D8%AF%D8%A7%D9%88%D8%AF_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85_%D9%88%D9%85%D8%A7_%D9%83%D8%A7%D9%86_%D9%81%D9%8A_%D8%A3%D9%8A%D8%A7%D9%85%D9%87_%D9%88%D8%B0%D9%83%D8%B1_%D9%81%D8%B6%D8%A7%D8%A6%D9%84%D9%87_%D9%88%D8%B4%D9%85%D8%A7%D8%A6%D9%84%D9%87_%D9%88%D8%AF%D9%84%D8%A7%D8%A6%D9%84_%D9%86%D8%A8%D9%88%D8%AA%D9%87_%D9%88%D8%A3%D8%B9%D9%84%D8%A7%D9%85%D9%87">قصصُ الأنبياء لابن كثير — قصة داود عليه السلام وما كان في أيامه وذكر فضائله وشمائله ودلائل نبوته وأعلامه</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: سليمانُ عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
