-- ٢٢) القصّةُ الثانية والعشرون: سليمانُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-sulaiman',
  'القصّةُ الثانية والعشرون: سليمانُ عليه السلام',
  'قال الله تعالى: {وورث سليمان داوود وقال يا أيها الناس علمنا منطق الطير وأوتينا من كل شيء إن هذا لهو الفضل المبين} أي ورثه في النبوة والملك، وليس…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{وَوَرِثَ سُلَيْمَٰنُ دَاوُۥدَ ۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ ۖ إِنَّ هَٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ} <strong>(سورة النمل ٢٧، الآية ١٦)</strong></p>
<p>{وَلِسُلَيْمَٰنَ ٱلرِّيحَ غُدُوُّهَا شَهْرٌۭ وَرَوَاحُهَا شَهْرٌۭ ۖ وَأَسَلْنَا لَهُۥ عَيْنَ ٱلْقِطْرِ ۖ وَمِنَ ٱلْجِنِّ مَن يَعْمَلُ بَيْنَ يَدَيْهِ بِإِذْنِ رَبِّهِۦ ۖ وَمَن يَزِغْ مِنْهُمْ عَنْ أَمْرِنَا نُذِقْهُ مِنْ عَذَابِ ٱلسَّعِيرِ} <strong>(سورة سبإ ٣٤، الآية ١٢)</strong></p>
<p>{قَالَ رَبِّ ٱغْفِرْ لِى وَهَبْ لِى مُلْكًۭا لَّا يَنۢبَغِى لِأَحَدٍۢ مِّنۢ بَعْدِىٓ ۖ إِنَّكَ أَنتَ ٱلْوَهَّابُ} <strong>(سورة صٓ ٣٨، الآية ٣٥)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>قال الله تعالى: {وورث سليمان داوود وقال يا أيها الناس علمنا منطق الطير وأوتينا من كل شيء إن هذا لهو الفضل المبين} أي ورثه في النبوة والملك، وليس المراد ورثه في المال، لأنه قد كان له بنون غيره، فما كان ليخص بالمال دونهم، ولأنه قد ثبت في الصحاح من غير وجه عن جماعة من الصحابة أن رسول الله صلى الله عليه وسلم قال: "لا نورث ما تركنا فهو صدقة" وفي لفظة: "نحن معاشر الأنبياء لا نورث" فأخبر الصادق المصدوق أن الأنبياء لا تورث أموالهم عنهم كما يورث غيرهم، بل تكون أموالهم صدقة من بعدهم على الفقراء والمحاويج لا يخصون بها أقربائهم، لأن الدنيا كانت أهون عليهم وأحقر عندهم من ذلك كما هي عند الذي أرسلهم واصطفاهم وفضلهم. وقال: {يا أيها الناس علمنا منطق الطير وأوتينا من كل شيء} يعني أنه عليه السلام كان يعرف ما يتخاطب به الطيور بلغاتها ويعبر للناس عن مقاصدها وإرادتها.</p>
<p>وقد قال الحافظ أبو بكر البيهقي: أنبأنا أبو عبد الله الحافظ، أنبأنا علي بن حشاد، حدثنا إسماعيل بن قتيبة، حدثنا علي بن قدامة، حدثنا أبو جعفر الأسواني، يعني محمد بن عبد الرحمن، عن أبي يعقوب العمي، حدثني أبو مالك. قال مر سليمان بن داود بعصفور يدور حول عصفورة فقال لأصحابه: أتدرون ما يقول؟ قالوا: وما يقول يا نبي الله؟ قال: يخطبها إلى نفسه ويقول زوجيني أسكنك أي غرف دمشق شئت! قال سليمان عليه السلام لأن غرف دمشق مبنية بالصخر، لا يقدر أن يسكنها أحد، ولكن كل خاطب كذاب.</p>
<p>رواه ابن عساكر عن أبي القاسم زاهر بن طاهر، عن البيهقي به وكذلك ما عداها من الحيوانات وسائر صنوف المخلوقات، والدليل على هذا قوله بعد هذا من الآيات: {وأوتينا من كل شيء} أي من كل ما يحتاج الملك إليه من العدد والآلات والجنود والجيوش والجماعات من الجن والإنس والطيور والوحوش والشياطين السارحات والعلوم والفهوم والتعبير عن ضمائر المخلوقات من الناطقات والصامتات ثم قال: {إن هذا لهو الفضل المبين} أي من بارئ البريات وخالق الأرض والسماوات كما قال تعالى: {وحشر لسليمان جنوده من الجن والإنس والطير فهم يوزعون، حتى إذا أتوا على وادي النمل قالت نملة يا أيها النمل ادخلوا مساكنكم لا يحطمنكم سليمان وجنوده وهم لا يشعرون، فتبسم ضاحكا من قولها وقال رب أوزعني أن أشكر نعمتك التي أنعمت علي وعلى والدي وأن أعمل صالحا ترضاه وأدخلني برحمتك في عبادك الصالحين}.</p>
<p>يخبر تعالى عن عبده ونبيه وابن نبيه سليمان بن داود عليهما الصلاة والسلام أنه ركب يوما في جيشه جميعه من الجن والإنس والطير، فالجن والإنس يسيرون معه والطير سائرة معه تظله بأجنحتها من الحر وغيره، وعلى كل من هذه الجيوش الثلاثة وزعة، أي نقباء يردون أوله على آخره، فلا يتقدم أحد عن موضعه الذي يسير فيه، ولا يتأخر عنه قال الله تعالى: {حتى إذا أتوا على وادي النمل قالت نملة يا أيها النمل ادخلوا مساكنكم لا يحطمنكم سليمان وجنوده وهم لا يشعرون} فأمرت وحذرت واعتذرت عن سليمان وجنوده بعدم الشعور. فقد ذكر وهب أنه مر وهو على البساط بواد بالطائف، وأن هذه النملة كان اسمها جرسن، وكانت من قبيلة يقال لهم بنو الشيصبان، وكانت عرجاء وكانت بقدر الذئب.</p>
<blockquote>البابُ في الكتاب: قصة سليمان بن داود عليهما السلام — الجزءُ الثاني، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D9%82%D8%B5%D8%A9_%D8%B3%D9%84%D9%8A%D9%85%D8%A7%D9%86_%D8%A8%D9%86_%D8%AF%D8%A7%D9%88%D8%AF_%D8%B9%D9%84%D9%8A%D9%87%D9%85%D8%A7_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة سليمان بن داود عليهما السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: زكرياُ عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D9%82%D8%B5%D8%A9_%D8%B3%D9%84%D9%8A%D9%85%D8%A7%D9%86_%D8%A8%D9%86_%D8%AF%D8%A7%D9%88%D8%AF_%D8%B9%D9%84%D9%8A%D9%87%D9%85%D8%A7_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
