-- ٢٣) القصّةُ الثالثة والعشرون: زكرياُ عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-zakariya',
  'القصّةُ الثالثة والعشرون: زكرياُ عليه السلام',
  'والمقصود أن الله تعالى أمر رسوله صلى الله عليه وسلم أن يقص على الناس خبر زكريا عليه السلام وما كان من أمره حين وهبه الله ولدا على الكبر وكانت امرأته…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُۥ زَكَرِيَّآ} <strong>(سورة مريم ١٩، الآية ٢)</strong></p>
<p>{إِذْ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيًّۭا} <strong>(سورة مريم ١٩، الآية ٣)</strong></p>
<p>{فَٱسْتَجَبْنَا لَهُۥ وَوَهَبْنَا لَهُۥ يَحْيَىٰ وَأَصْلَحْنَا لَهُۥ زَوْجَهُۥٓ ۚ إِنَّهُمْ كَانُوا۟ يُسَٰرِعُونَ فِى ٱلْخَيْرَٰتِ وَيَدْعُونَنَا رَغَبًۭا وَرَهَبًۭا ۖ وَكَانُوا۟ لَنَا خَٰشِعِينَ} <strong>(سورة الأنبياء ٢١، الآية ٩٠)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>والمقصود أن الله تعالى أمر رسوله صلى الله عليه وسلم أن يقص على الناس خبر زكريا عليه السلام وما كان من أمره حين وهبه الله ولدا على الكبر وكانت امرأته مع ذلك عاقرا في حال شيبتها وقد أسنت أيضا، حتى لا ييأس من فضل الله ورحمته ولا يقنط من فضله تعالى {ذكر رحمة ربك عبده زكريا، إذ نادى ربه نداء خفيا}. قال قتادة عند تفسيرها: إن الله يعلم القلب النقي ويسمع الصوت الخفي. وقال بعض السلف: قام من الليل فنادى ربه مناداة أسرها عمن كان حاضرا عنده مخافته فقال: يا رب يا رب يا رب. فقال الله: لبيك لبيك لبيك. {قال رب إني وهن العظم مني} أي ضعف وخار من الكبر {واشتعل الرأس شيبا} استعارة من اشتعال النار في الحطب أي غلب على سواد الشعر شيبه كما قال ابن دريد في مقصورته:</p>
<p>يذكر أن الضعف قد استحوذ عليه باطنا وظاهرا. وهكذا قال زكريا عليه السلام { إني وهن العظم مني واشتعل الرأس شيبا}.</p>
<p>وقوله {ولم أكن بدعائك رب شقيا} أي ما عودتني فيما أسألك إلا الإجابة وكان الباعث له على هذه "المسألة" أنه لما كفل مريم بنت عمران بن ماثان، وكان كلما دخل عليها محرابها وجد عندها فاكهة في غير إبانها ولا في أوانها وهذه من كرامات الأولياء، فعلم أن الرزاق للشيء في غير أوانه قادر على أن يرزقه ولدا وإن كان قد طعن في سنه {هنالك دعا زكريا ربه قال رب هب لي من لدنك ذرية طيبة إنك سميع الدعاء} وقوله: {وإني خفت الموالي من ورائي وكانت امرأتي عاقرا} قيل المراد بالموالي العصبة، وكأنه خاف من تصرفهم بعده في بني إسرائيل بما لا يوافق شرع الله وطاعته فسأل وجود ولد من صلبه يكون برا تقيا مرضيا ولهذا قال: {فهب لي من لدنك} أي من عندك بحولك وقوتك {وليا يرثني } أي في النبوة والحكم في بني إسرائيل {ويرث من آل يعقوب واجعله رب رضيا} يعني كما كان آباؤه وأسلافه من ذرية يعقوب أنبياء فاجعله مثلهم في الكرامة التي أكرمتهم بها من النبوة والوحي، وليس المراد هاهنا وراثة المال كما زعم ذلك من زعمه من الشيعة ووافقهم ابن جرير ها هنا وحكاه عن أبي صالح من السلف، لوجوه:</p>
<blockquote>البابُ في الكتاب: قصة زكريا ويحيى عليهما السلام — الجزءُ الثاني، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D9%82%D8%B5%D8%A9_%D8%B2%D9%83%D8%B1%D9%8A%D8%A7_%D9%88%D9%8A%D8%AD%D9%8A%D9%89_%D8%B9%D9%84%D9%8A%D9%87%D9%85%D8%A7_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — قصة زكريا ويحيى عليهما السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: يحيى عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D9%82%D8%B5%D8%A9_%D8%B2%D9%83%D8%B1%D9%8A%D8%A7_%D9%88%D9%8A%D8%AD%D9%8A%D9%89_%D8%B9%D9%84%D9%8A%D9%87%D9%85%D8%A7_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
  'ويكي مصدر — قصص الأنبياء لابن كثير',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A',
  '["زكريا عليه السلام","قصص الأنبياء","ابن كثير"]'::jsonb,
  '{"القصّة":"٢٣ من ٢٥","الكتاب":"قصص الأنبياء — ابن كثير (جزؤه الثاني)","الباب":"قصة زكريا ويحيى عليهما السلام","الرخصة":"ويكي مصدر — رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)"}'::jsonb,
  'published', 30,
