-- ٢٤) القصّةُ الرابعة والعشرون: يحيى عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-yahya',
  'القصّةُ الرابعة والعشرون: يحيى عليه السلام',
  'وذكروا في قتله أسبابا من أشهرها أن بعض ملوك ذلك الزمان بدمشق كان يريد أن يتزوج ببعض محارمه أو من لا يحل له تزويجها، فنهاه يحيى عليه السلام عن ذلك…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{يَٰيَحْيَىٰ خُذِ ٱلْكِتَٰبَ بِقُوَّةٍۢ ۖ وَءَاتَيْنَٰهُ ٱلْحُكْمَ صَبِيًّۭا} <strong>(سورة مريم ١٩، الآية ١٢)</strong></p>
<p>{وَحَنَانًۭا مِّن لَّدُنَّا وَزَكَوٰةًۭ ۖ وَكَانَ تَقِيًّۭا} <strong>(سورة مريم ١٩، الآية ١٣)</strong></p>
<p>{فَنَادَتْهُ ٱلْمَلَٰٓئِكَةُ وَهُوَ قَآئِمٌۭ يُصَلِّى فِى ٱلْمِحْرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحْيَىٰ مُصَدِّقًۢا بِكَلِمَةٍۢ مِّنَ ٱللَّهِ وَسَيِّدًۭا وَحَصُورًۭا وَنَبِيًّۭا مِّنَ ٱلصَّٰلِحِينَ} <strong>(سورة آل عمران ٣، الآية ٣٩)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>وذكروا في قتله أسبابا من أشهرها أن بعض ملوك ذلك الزمان بدمشق كان يريد أن يتزوج ببعض محارمه أو من لا يحل له تزويجها، فنهاه يحيى عليه السلام عن ذلك فبقي في نفسه منه فلما كان بينهما وبين الملك ما يحب منها إستوهبت منه دم يحيى، فوهبه لها فبعثت إليه من قتله وجاء برأسه ودمه في طست الى عندها فيقال انها هلكت من فورها وساعتها.</p>
<p>و قيل: بل أحبته امرأة ذلك الملك وراسلته فأبى عليها، فلما يئست منه تحيلت في أن إستوهبته من الملك، فتمنع عليها الملك ثم أجابها إلى ذلك فبعث من قتله وأحضر إليها رأسه ودمه في طست.</p>
<p>وقد ورد معناه في حديث رواه إسحاق بن بشر في كتابه المبتدأ حيث قال: أنبأنا يعقوب الكوفي، عن عمرو بن ميمون، عن أبيه، عن ابن عباس، أن رسول الله صلى الله عليه وسلم ليلة أسري به رأى زكريا في السماء فسلم عليه وقال له: يا أبا يحيى خبرني عن قتلك كيف كان ولم قتلك بنو إسرائيل؟ قال: يا محمد أخبرك أن يحيى كان خير أهل زمانه، وكان أجملهم وأصبحهم وجها، وكان كما قال الله تعالى: {وسيدا وحصورا} وكان لا يحتاج إلى النساء فهويته امرأة ملك بني إسرائيل، وكانت بغية، فأرسلت إليه وعصمه الله وامتنع يحيى وأبى عليها فأجمعت على قتل يحيى ولهم عيد يجتمعون في كل عام، وكانت سنة الملك أن يعد ولا يخلف ولا يكذب.</p>
<blockquote>البابُ في الكتاب: بيان سبب قتل يحيى عليه السلام — الجزءُ الثاني، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D8%A8%D9%8A%D8%A7%D9%86_%D8%B3%D8%A8%D8%A8_%D9%82%D8%AA%D9%84_%D9%8A%D8%AD%D9%8A%D9%89_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85">قصصُ الأنبياء لابن كثير — بيان سبب قتل يحيى عليه السلام</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>القصةُ التالية: عيسى ابنُ مريم عليه السلام.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D8%A8%D9%8A%D8%A7%D9%86_%D8%B3%D8%A8%D8%A8_%D9%82%D8%AA%D9%84_%D9%8A%D8%AD%D9%8A%D9%89_%D8%B9%D9%84%D9%8A%D9%87_%D8%A7%D9%84%D8%B3%D9%84%D8%A7%D9%85',
