-- ٢٥) القصّةُ الخامسة والعشرون: عيسى ابنُ مريم عليه السلام
insert into public.items
  (section_id, slug, title, subtitle, body, link, source_name, source_url,
   tags, fields, status, sort_order, published_at)
select
  'prophets_stories',
  'prophet-isa',
  'القصّةُ الخامسة والعشرون: عيسى ابنُ مريم عليه السلام',
  'وقد تقدم أن مريم لما جعلتها أمها محررة تخدم بيت المقدس، وأنه كفلها زوج أختها أو خالتها نبي ذلك الزمان زكريا عليه السلام، وأنه اتخذ لها محرابا وهو…',
  '<h2>آياتٌ من القرآنِ في شأنِه</h2>
<p>{إِذْ قَالَتِ ٱلْمَلَٰٓئِكَةُ يَٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍۢ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًۭا فِى ٱلدُّنْيَا وَٱلْءَاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ} <strong>(سورة آل عمران ٣، الآية ٤٥)</strong></p>
<p>{قَالَتْ رَبِّ أَنَّىٰ يَكُونُ لِى وَلَدٌۭ وَلَمْ يَمْسَسْنِى بَشَرٌۭ ۖ قَالَ كَذَٰلِكِ ٱللَّهُ يَخْلُقُ مَا يَشَآءُ ۚ إِذَا قَضَىٰٓ أَمْرًۭا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ} <strong>(سورة آل عمران ٣، الآية ٤٧)</strong></p>
<p>{قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَٰبَ وَجَعَلَنِى نَبِيًّۭا} <strong>(سورة مريم ١٩، الآية ٣٠)</strong></p>
<h2>من «قصص الأنبياء» لابن كثير</h2>
<p>وقد تقدم أن مريم لما جعلتها أمها محررة تخدم بيت المقدس، وأنه كفلها زوج أختها أو خالتها نبي ذلك الزمان زكريا عليه السلام، وأنه اتخذ لها محرابا وهو المكان الشريف من المسجد لا يدخله أحد عليها سواه، وأنها لما بلغت اجتهدت في العبادة فلم يكن في ذلك الزمان نظيرها في فنون العبادات، وظهر عليها من الأحوال ما غبطها به زكريا عليه السلام وأنها خاطبتها الملائكة بالبشارة لها باصطفاء الله لها، وبأنه سيهب لها ولدا زكيا يكون نبيا كريما طاهرا مكرما مؤيدا بالمعجزات، فتعجبت من وجود ولد من غير والد، لأنها لا زوج لها، ولا هي ممن تتزوج فاخبرتها الملائكة بأن الله قادر على ما يشاء إذا قضى أمرا فإنما يقول له كن فيكون، فاستكانت لذلك وأنابت وسلمت لأمر الله، وعلمت أن هذا فيه محنة عظيمة لها، فإن الناس يتكلمون فيها بسببه، لأنهم لا يعلمون حقيقة الأمر، وإنما ينظرون إلى ظاهر الحال من غير تدبر ولا تعقل.</p>
<p>وكانت إنما تخرج من المسجد في زمن حيضها أو لحاجة ضرورة لابد منها من استقاء ماء أو تحصيل غذاء، فبينما هي يوما قد خرجت لبعض شؤونها و{انتبذت} أي انفردت وحدها شرقي المسجد الأقصى إذ بعث الله إليها الروح الأمين جبريل عليه السلام {فتمثل لها بشرا سويا} فلما رأته {قالت إني أعوذ بالرحمان منك إن كنت تقيا} قال أبو العالية: علمت أن التقي ذو نهية. وهذا يرد قول من زعم أنه كان في بني إسرائيل رجل فاسق مشهور بالفسق اسمه "تقي" فإن هذا قول باطل بلا دليل، وهو من أسخف الأقوال.</p>
<p>{قال إنما أنا رسول ربك} أي خاطبها الملك قائلا {قال إنما أنا رسول ربك} أي لست ببشر ولكني ملك بعثني الله إليك {لأهب لك غلاما زكيا} أي ولدا زكيا.</p>
<p>{قالت أنى يكون لي غلام} أي كيف يكون لي غلام أو يوجد لي ولد {ولم يمسسني بشر ولم أكن بغيا} أي ولست ذات زوج وما أنا ممن يفعل الفاحشة { قال كذلك قال ربك هو علي هين} أي فأجابها الملك عن تعجبها من وجود ولد منها والحالة هذه قائلا {كذلك قال ربك} أي وعد أنه سيخلق منك غلاما ولست بذات بعل ولا تكونين ممن تبغين {هو علي هين} أي وهذا أسهل عليه ويسير لديه، فإنه على ما يشاء قدير.</p>
<p>وقوله {ولنجعله آية للناس} أي ولنجعل خلقه والحالة هذه دليلا على كمال قدرتنا على أنواع الخلق، فإنه تعالى خلق آدم من غير ذكر ولا أنثى، وخلق حواء من ذكر بلا أنثى، وخلق عيسى من أنثى بلا ذكر، وخلق بقية الخلق من ذكر وأنثى. وقوله {ورحمة منا} أي نرحم به العباد بأن يدعوهم إلى الله في صغره وكبره في طفوليته وكهوليته، بأن يفردوا الله بالعبادة وحده لا شريك له وينزهوه عن اتخاذ الصاحبة والأولاد والشركاء والنظراء والأضداد والأنداد.</p>
<p>وقوله: {وكان أمرا مقضيا}. يحتمل أن يكون هذا من تمام كلام جبريل معها، يعني أن هذا أمر قد قضاه الله وحتمه وقدره وقرره، وهذا معنى قول محمد بن إسحاق واختاره ابن جرير، ولم يحك سواه. والله أعلم.</p>
<p>ويحتمل أن يكون قوله {وكان أمرا مقضيا} كناية عن نفخ جبريل فيها كما قال تعالى: {ومريم ابنت عمران التي أحصنت فرجها فنفخنا فيه من روحنا}.</p>
<blockquote>البابُ في الكتاب: ذكر ميلاد العبد الرسول عيسى بن مريم العذراء البتول — الجزءُ الثاني، ومنشورٌ في مصدرِه: <a href="https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D8%B0%D9%83%D8%B1_%D9%85%D9%8A%D9%84%D8%A7%D8%AF_%D8%A7%D9%84%D8%B9%D8%A8%D8%AF_%D8%A7%D9%84%D8%B1%D8%B3%D9%88%D9%84_%D8%B9%D9%8A%D8%B3%D9%89_%D8%A8%D9%86_%D9%85%D8%B1%D9%8A%D9%85_%D8%A7%D9%84%D8%B9%D8%B0%D8%B1%D8%A7%D8%A1_%D8%A7%D9%84%D8%A8%D8%AA%D9%88%D9%84">قصصُ الأنبياء لابن كثير — ذكر ميلاد العبد الرسول عيسى بن مريم العذراء البتول</a>. والنصُّ مأخوذٌ من ويكي مصدر بنسختِها المرخَّصة بـ«رخصة المشاع الإبداعي — النسبة، المشاركة بالمثل 4.0 (CC BY-SA 4.0)»، والنقلُ هنا بنسبةِ المصدرِ لا بتصرُّفٍ في كلامه.</blockquote>
<p>انتهت القصصُ على ترتيبِ الكتاب، وكتابُ «قصص الأنبياء» الذي بين أيدينا يقفُ عند عيسى عليه السلام؛ أما سيرةُ النبيِّ محمدٍ صلَّى اللهُ عليهِ وسلَّم فموضعُها كُتُبُ السيرة لا هذا الباب.</p>',
  'https://ar.wikisource.org/wiki/%D9%82%D8%B5%D8%B5_%D8%A7%D9%84%D8%A3%D9%86%D8%A8%D9%8A%D8%A7%D8%A1_%D9%84%D8%A7%D8%A8%D9%86_%D9%83%D8%AB%D9%8A%D8%B1/%D8%A7%D9%84%D8%AC%D8%B2%D8%A1_%D8%A7%D9%84%D8%AB%D8%A7%D9%86%D9%8A#%D8%B0%D9%83%D8%B1_%D9%85%D9%8A%D9%84%D8%A7%D8%AF_%D8%A7%D9%84%D8%B9%D8%A8%D8%AF_%D8%A7%D9%84%D8%B1%D8%B3%D9%88%D9%84_%D8%B9%D9%8A%D8%B3%D9%89_%D8%A8%D9%86_%D9%85%D8%B1%D9%8A%D9%85_%D8%A7%D9%84%D8%B9%D8%B0%D8%B1%D8%A7%D8%A1_%D8%A7%D9%84%D8%A8%D8%AA%D9%88%D9%84',
