-- تدقيقٌ بعد التنفيذ: خمسةٌ وعشرون عنصرًا؟ والبابُ والمصدرُ محفوظٌ في كلٍّ منها؟
do $$
declare n int; miss int;
begin
  select count(*) into n from public.items where section_id = 'prophets_stories';
  select count(*) into miss from public.items where section_id = 'prophets_stories'
    and (fields->>'الباب' is null or source_url is null or link is null
         or length(link) > 500 or link ~ '%([0-9a-fA-F]?)$');
  if n <> 25 then raise warning 'WARNING: القصصُ المنشورةُ % بدلًا من % — أكملْ بذرةَ الناقصِ منها.', n, 25; end if;
  if miss > 0 then raise warning 'WARNING: % عنصرًا في قسمِ القصصِ بلا مصدرٍ كامل.', miss; end if;
end $$;

select i.slug, i.title, i.sort_order,
  length(i.body) as body_chars,
  coalesce(i.fields->>'القصّة','—') as no,
  coalesce(i.fields->>'الباب','—') as bab
from public.items i where i.section_id = 'prophets_stories' order by i.sort_order desc;
